"somalia\":\"so\",\"federal republic of somalia\":\"so\",\"saint pierre and miquelon\":\"pm\",\"serbia\":\"rs\",\"republic of serbia\":\"rs\",\"south sudan\":\"ss\",\"republic of south sudan\":\"ss\",\"sao tome and principe\":\"st\",\"democratic republic of sao tome and principe\":\"st\",\"suriname\":\"sr\",\"republic of suriname\":\"sr\",\"slovakia\":\"sk\",\"slovak republic\":\"sk\",\"slovenia\":\"si\",\"republic of slovenia\":\"si\",\"sweden\":\"se\",\"kingdom of sweden\":\"se\",\"eswatini\":\"sz\",\"kingdom of eswatini\":\"sz\",\"sint maarten (dutch part)\":\"sx\",\"seychelles\":\"sc\",\"republic of seychelles\":\"sc\",\"syrian arab republic\":\"sy\",\"syria\":\"sy\",\"turks and caicos islands\":\"tc\",\"chad\":\"td\",\"republic of chad\":\"td\",\"togo\":\"tg\",\"togolese republic\":\"tg\",\"thailand\":\"th\",\"kingdom of thailand\":\"th\",\"tajikistan\":\"tj\",\"republic of tajikistan\":\"tj\",\"tokelau\":\"tk\",\"turkmenistan\":\"tm\",\"timor-leste\":\"tl\",\"democratic republic of timor-leste\":\"tl\",\"tonga\":\"to\",\"kingdom of tonga\":\"to\",\"trinidad and tobago\":\"tt\",\"republic of trinidad and tobago\":\"tt\",\"tunisia\":\"tn\",\"republic of tunisia\":\"tn\",\"türkiye\":\"tr\",\"republic of türkiye\":\"tr\",\"tuvalu\":\"tv\",\"taiwan, province of china\":\"tw\",\"taiwan\":\"tw\",\"tanzania, united republic of\":\"tz\",\"united republic of tanzania\":\"tz\",\"tanzania\":\"tz\",\"uganda\":\"ug\",\"republic of uganda\":\"ug\",\"ukraine\":\"ua\",\"united states minor outlying islands\":\"um\",\"uruguay\":\"uy\",\"eastern republic of uruguay\":\"uy\",\"united states\":\"us\",\"united states of america\":\"us\",\"uzbekistan\":\"uz\",\"republic of uzbekistan\":\"uz\",\"holy see (vatican city state)\":\"va\",\"saint vincent and the grenadines\":\"vc\",\"venezuela, bolivarian republic of\":\"ve\",\"bolivarian republic of venezuela\":\"ve\",\"venezuela\":\"ve\",\"virgin islands, british\":\"vg\",\"british virgin islands\":\"vg\",\"virgin islands, u.s\":\"vi\",\"virgin islands of the united states\":\"vi\",\"viet nam\":\"vn\",\"socialist republic of viet nam\":\"vn\",\"vietnam\":\"vn\",\"vanuatu\":\"vu\",\"republic of vanuatu\":\"vu\",\"wallis and futuna\":\"wf\",\"samoa\":\"ws\",\"independent state of samoa\":\"ws\",\"yemen\":\"ye\",\"republic of yemen\":\"ye\",\"south africa\":\"za\",\"republic of south africa\":\"za\",\"zambia\":\"zm\",\"republic of zambia\":\"zm\",\"zimbabwe\":\"zw\",\"republic of zimbabwe\":\"zw\",\"holland\":\"nl\",\"usa\":\"us\",\"u.s.a\":\"us\",\"uk\":\"gb\",\"great britain\":\"gb\",\"britain\":\"gb\",\"korea, south\":\"kr\",\"republic of korea\":\"kr\",\"korea, north\":\"kp\",\"russia\":\"ru\",\"taiwan, china\":\"tw\",\"turkey\":\"tr\",\"brunei\":\"bn\",\"macedonia\":\"mk\",\"ivory coast\":\"ci\",\"swaziland\":\"sz\",\"burma\":\"mm\",\"cape verde\":\"cv\",\"palestine\":\"ps\",\"macau\":\"mo\",\"kosovo\":\"xk\",\"dr congo\":\"cd\",\"democratic republic of the congo\":\"cd\",\"micronesia\":\"fm\"};\n\t\tconst networkCountryFlagCodes = new Set([\"ad\",\"ae\",\"af\",\"ag\",\"ai\",\"al\",\"am\",\"ao\",\"aq\",\"ar\",\"as\",\"at\",\"au\",\"aw\",\"ax\",\"az\",\"ba\",\"bb\",\"bd\",\"be\",\"bf\",\"bg\",\"bh\",\"bi\",\"bj\",\"bl\",\"bm\",\"bn\",\"bo\",\"bq\",\"br\",\"bs\",\"bt\",\"bv\",\"bw\",\"by\",\"bz\",\"ca\",\"cc\",\"cd\",\"cf\",\"cg\",\"ch\",\"ci\",\"ck\",\"cl\",\"cm\",\"cn\",\"co\",\"cr\",\"cu\",\"cv\",\"cw\",\"cx\",\"cy\",\"cz\",\"de\",\"dj\",\"dk\",\"dm\",\"do\",\"dz\",\"ec\",\"ee\",\"eg\",\"eh\",\"er\",\"es\",\"et\",\"fi\",\"fj\",\"fk\",\"fm\",\"fo\",\"fr\",\"ga\",\"gb\",\"gd\",\"ge\",\"gf\",\"gg\",\"gh\",\"gi\",\"gl\",\"gm\",\"gn\",\"gp\",\"gq\",\"gr\",\"gs\",\"gt\",\"gu\",\"gw\",\"gy\",\"hk\",\"hm\",\"hn\",\"hr\",\"ht\",\"hu\",\"id\",\"ie\",\"il\",\"im\",\"in\",\"io\",\"iq\",\"ir\",\"is\",\"it\",\"je\",\"jm\",\"jo\",\"jp\",\"ke\",\"kg\",\"kh\",\"ki\",\"km\",\"kn\",\"kp\",\"kr\",\"kw\",\"ky\",\"kz\",\"la\",\"lb\",\"lc\",\"li\",\"lk\",\"lr\",\"ls\",\"lt\",\"lu\",\"lv\",\"ly\",\"ma\",\"mc\",\"md\",\"me\",\"mf\",\"mg\",\"mh\",\"mk\",\"ml\",\"mm\",\"mn\",\"mo\",\"mp\",\"mq\",\"mr\",\"ms\",\"mt\",\"mu\",\"mv\",\"mw\",\"mx\",\"my\",\"mz\",\"na\",\"nc\",\"ne\",\"nf\",\"ng\",\"ni\",\"nl\",\"no\",\"np\",\"nr\",\"nu\",\"nz\",\"om\",\"pa\",\"pe\",\"pf\",\"pg\",\"ph\",\"pk\",\"pl\",\"pm\",\"pn\",\"pr\",\"ps\",\"pt\",\"pw\",\"py\",\"qa\",\"re\",\"ro\",\"rs\",\"ru\",\"rw\",\"sa\",\"sb\",\"sc\",\"sd\",\"se\",\"sg\",\"sh\",\"si\",\"sj\",\"sk\",\"sl\",\"sm\",\"sn\",\"so\",\"sr\",\"ss\",\"st\",\"sv\",\"sx\",\"sy\",\"sz\",\"tc\",\"td\",\"tf\",\"tg\",\"th\",\"tj\",\"tk\",\"tl\",\"tm\",\"tn\",\"to\",\"tr\",\"tt\",\"tv\",\"tw\",\"tz\",\"ua\",\"ug\",\"um\",\"us\",\"uy\",\"uz\",\"va\",\"vc\",\"ve\",\"vg\",\"vi\",\"vn\",\"vu\",\"wf\",\"ws\",\"ye\",\"yt\",\"za\",\"zm\",\"zw\"]);\n\t\tfunction getNetworkCountryFlagCode(countryText) {\n\t\t\tconst text = String(countryText || '').trim();\n\t\t\tif (!text) return '';\n\n\t\t\t// Some providers return an ISO code before the ASN, e.g. \"NL AS400940 Railway\".\n\t\t\tconst codeMatch = text.match(/^([a-zA-Z]{2})(?:\\s|$)/);\n\t\t\tif (codeMatch && networkCountryFlagCodes.has(codeMatch[1].toLowerCase())) {\n\t\t\t\treturn codeMatch[1].toLowerCase();\n\t\t\t}\n\n\t\t\t// Strip the ASN/provider suffix and map the country name to its ISO alpha-2 code.\n\t\t\tconst asnStart = text.search(/\\s+AS\\d+\\b/i);\n\t\t\tconst countryLabel = (asnStart >= 0 ? text.slice(0, asnStart) : text).trim();\n\t\t\tconst normalized = countryLabel.toLocaleLowerCase('en-US')\n\t\t\t\t.replace(/^the\\s+/, '').replace(/[.,]$/, '').replace(/\\s+/g, ' ');\n\t\t\treturn networkCountryFlagLookup[normalized] || '';\n\t\t}\n\n\t\tfunction applyNetworkCardFlag(countryElementId) {\n\t\t\tconst countryElement = document.getElementById(countryElementId);\n\t\t\tif (!countryElement) return;\n\n\t\t\tconst networkCard = countryElement.closest('.network-card');\n\t\t\tif (!networkCard) return;\n\n\t\t\tconst countryText = String(countryElement.dataset.rawValue || countryElement.textContent || '').trim();\n\t\t\tconst countryCode = getNetworkCountryFlagCode(countryText);\n\n\t\t\tif (!countryCode) {\n\t\t\t\tnetworkCard.classList.remove('has-flag-badge');\n\t\t\t\tnetworkCard.style.removeProperty('--flag-badge-url');\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\tnetworkCard.style.setProperty('--flag-badge-url', `url(\"https://ipdata.co/flags/${countryCode}.png\")`);\n\t\t\tnetworkCard.classList.add('has-flag-badge');\n\t\t}\n\n\t\t// JSONP 请求工具（用于None CORS 的接口）\n\t\tfunction createJsonpRequest(url, callbackParam, timeoutMs = NETWORK_API_TIMEOUT_MS) {\n\t\t\tlet settled = false;\n\t\t\tlet timeoutId = null;\n\t\t\tlet script = null;\n\t\t\tlet callbackScope = null;\n\t\t\tlet callbackKey = null;\n\t\t\tlet rejectPromise = null;\n\n\t\t\tconst cleanup = () => {\n\t\t\t\tif (timeoutId) {\n\t\t\t\t\tclearTimeout(timeoutId);\n\t\t\t\t\ttimeoutId = null;\n\t\t\t\t}\n\t\t\t\tif (script && script.parentNode) {\n\t\t\t\t\tscript.parentNode.removeChild(script);\n\t\t\t\t}\n\t\t\t\tif (callbackScope && callbackKey) {\n\t\t\t\t\ttry {\n\t\t\t\t\t\tdelete callbackScope[callbackKey];\n\t\t\t\t\t} catch {\n\t\t\t\t\t\tcallbackScope[callbackKey] = undefined;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t};\n\n\t\t\tconst promise = new Promise((resolve, reject) => {\n\t\t\t\trejectPromise = reject;\n\n\t\t\t\tconst finalize = (handler, value) => {\n\t\t\t\t\tif (settled) return;\n\t\t\t\t\tsettled = true;\n\t\t\t\t\tcleanup();\n\t\t\t\t\thandler(value);\n\t\t\t\t};\n\n\t\t\t\tconst callbackPath = `window.__EDT2_IP_TEST_.__${Date.now()}_${Math.floor(Math.random() * 1e16)}__`;\n\t\t\t\tconst callbackChain = callbackPath.replace(/^window\\./, '').split('.');\n\n\t\t\t\tcallbackScope = window;\n\t\t\t\tfor (let i = 0; i < callbackChain.length - 1; i++) {\n\t\t\t\t\tconst key = callbackChain[i];\n\t\t\t\t\tif (!callbackScope[key] || typeof callbackScope[key] !== 'object') {\n\t\t\t\t\t\tcallbackScope[key] = {};\n\t\t\t\t\t}\n\t\t\t\t\tcallbackScope = callbackScope[key];\n\t\t\t\t}\n\t\t\t\tcallbackKey = callbackChain[callbackChain.length - 1];\n\t\t\t\tcallbackScope[callbackKey] = payload => finalize(resolve, payload);\n\n\t\t\t\tconst requestUrl = new URL(url);\n\t\t\t\trequestUrl.searchParams.set(callbackParam, callbackPath);\n\t\t\t\trequestUrl.searchParams.set('_t', Date.now().toString());\n\n\t\t\t\tscript = document.createElement('script');\n\t\t\t\tscript.src = requestUrl.toString();\n\t\t\t\tscript.async = true;\n\t\t\t\tscript.referrerPolicy = 'no-referrer';\n\t\t\t\tscript.onerror = () => finalize(reject, new Error(`JSONP load failed: ${url}`));\n\n\t\t\t\ttimeoutId = setTimeout(() => {\n\t\t\t\t\tfinalize(reject, new Error(`JSONP timeout: ${url}`));\n\t\t\t\t}, timeoutMs);\n\n\t\t\t\tdocument.head.appendChild(script);\n\t\t\t});\n\n\t\t\treturn {\n\t\t\t\tpromise,\n\t\t\t\tcancel: () => {\n\t\t\t\t\tif (!settled && rejectPromise) {\n\t\t\t\t\t\tsettled = true;\n\t\t\t\t\t\tcleanup();\n\t\t\t\t\t\trejectPromise(new Error(`JSONP cancelled: ${url}`));\n\t\t\t\t\t} else {\n\t\t\t\t\t\tcleanup();\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t};\n\t\t}\n\n\t\t// 统一调用 IP Details接口（按 IP 查询）\n\t\tasync function fetchIpInfoByIp(ip) {\n\t\t\tconst requestIp = String(ip || '').trim();\n\t\t\tif (!requestIp) {\n\t\t\t\tthrow new Error('missing ip');\n\t\t\t}\n\n\t\t\t// Keep the current service first; use ipapi.is only when its response has no usable location.\n\t\t\t// ipapi.is changed its anonymous response fields in September 2026.\n\t\t\tconst apis = [\n\t\t\t\t{\n\t\t\t\t\tname: 'cm-cf',\n\t\t\t\t\turl: `https://api.090227.xyz/api/ipsb?ip=${encodeURIComponent(requestIp)}`\n\t\t\t\t},\n\t\t\t\t{\n\t\t\t\t\tname: 'ipapi.is',\n\t\t\t\t\turl: `https://api.ipapi.is/?q=${encodeURIComponent(requestIp)}`\n\t\t\t\t}\n\t\t\t];\n\n\t\t\tconst errors = [];\n\t\t\tfor (const api of apis) {\n\t\t\t\ttry {\n\t\t\t\t\tconst response = await fetchWithTimeout(api.url, { cache: 'no-store' });\n\t\t\t\t\tif (!response.ok) {\n\t\t\t\t\t\tthrow new Error(`${api.name} HTTP ${response.status}`);\n\t\t\t\t\t}\n\t\t\t\t\tconst data = await response.json();\n\t\t\t\t\tif (!data || typeof data !== 'object' || data.error) {\n\t\t\t\t\t\tthrow new Error(`${api.name} invalid payload`);\n\t\t\t\t\t}\n\t\t\t\t\tif (formatIpInfoLocation(data) === 'Unknown') {\n\t\t\t\t\t\tthrow new Error(`${api.name} returned no location metadata`);\n\t\t\t\t\t}\n\t\t\t\t\treturn data;\n\t\t\t\t} catch (error) {\n\t\t\t\t\terrors.push(`${api.name}: ${error?.message || error}`);\n\t\t\t\t\tconsole.warn(`[IP Location] ${api.name} failed for ${requestIp}:`, error);\n\t\t\t\t}\n\t\t\t}\n\t\t\tthrow new Error(`No IP location provider succeeded for ${requestIp}: ${errors.join('; ')}`);\n\t\t}\n\n\t\tfunction formatIpInfoLocation(info) {\n\t\t\t// Supports both legacy providers and the current anonymous ipapi.is response schema.\n\t\t\tconst location = info?.location && typeof info.location === 'object' ? info.location : {};\n\t\t\tconst country = String(\n\t\t\t\tinfo?.country_code || info?.cc || location.country_code ||\n\t\t\t\tinfo?.country || location.country || info?.country_name || ''\n\t\t\t).trim();\n\n\t\t\tconst rawAsn = info?.asn_num ?? info?.asn ?? info?.autonomous_system_number ?? location.asn;\n\t\t\tlet asnText = '';\n\t\t\tlet embeddedOrg = '';\n\t\t\tif (rawAsn !== undefined && rawAsn !== null && rawAsn !== '') {\n\t\t\t\tif (typeof rawAsn === 'object') {\n\t\t\t\t\tconst nestedNumber = rawAsn.asn ?? rawAsn.number ?? rawAsn.asn_num;\n\t\t\t\t\tif (nestedNumber !== undefined && nestedNumber !== null && String(nestedNumber).trim()) {\n\t\t\t\t\t\tconst n = String(nestedNumber).trim();\n\t\t\t\t\t\tasnText = /^AS/i.test(n) ? n.toUpperCase() : `AS${n}`;\n\t\t\t\t\t}\n\t\t\t\t\tembeddedOrg = String(rawAsn.org || rawAsn.organization || rawAsn.descr || rawAsn.name || '').trim();\n\t\t\t\t} else {\n\t\t\t\t\tconst raw = String(rawAsn).trim();\n\t\t\t\t\tconst match = raw.match(/^(AS\\d+)(?:\\s+(.+))?$/i);\n\t\t\t\t\tif (match) {\n\t\t\t\t\t\tasnText = match[1].toUpperCase();\n\t\t\t\t\t\tembeddedOrg = String(match[2] || '').trim();\n\t\t\t\t\t} else if (/^\\d+$/.test(raw)) {\n\t\t\t\t\t\tasnText = `AS${raw}`;\n\t\t\t\t\t} else {\n\t\t\t\t\t\t// Some providers already return the complete ASN label, e.g. \"AS12345 Example ISP\".\n\t\t\t\t\t\tasnText = raw;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\n\t\t\tconst company = typeof info?.company === 'string'\n\t\t\t\t? info.company\n\t\t\t\t: (info?.company?.name || info?.company?.org || '');\n\t\t\tconst asnName = String(\n\t\t\t\tinfo?.as_name || info?.asn_organization || info?.organization ||\n\t\t\t\tinfo?.isp || info?.as_org || embeddedOrg ||\n\t\t\t\tinfo?.asn?.org || info?.asn?.descr || company || ''\n\t\t\t).trim();\n\n\t\t\tconst parts = [country, asnText, asnName].filter(Boolean);\n\t\t\treturn parts.join(' ').trim() || 'Unknown';\n\t\t}\n\n\t\tfunction createIpProbeRequestTask(sourceConfig) {\n\t\t\tif (sourceConfig.type === 'jsonp') {\n\t\t\t\tconst jsonpTask = createJsonpRequest(sourceConfig.url, sourceConfig.callbackParam);\n\t\t\t\treturn {\n\t\t\t\t\tcancel: jsonpTask.cancel,\n\t\t\t\t\tpromise: jsonpTask.promise.then(payload => {\n\t\t\t\t\t\tconst requestIp = String(sourceConfig.extractIp(payload) || '').trim();\n\t\t\t\t\t\tif (!requestIp) {\n\t\t\t\t\t\t\tthrow new Error(`${sourceConfig.url} missing jsonp ip`);\n\t\t\t\t\t\t}\n\t\t\t\t\t\treturn {\n\t\t\t\t\t\t\tsource: sourceConfig.url,\n\t\t\t\t\t\t\trequestIp,\n\t\t\t\t\t\t\tproviderName: sourceConfig.name\n\t\t\t\t\t\t};\n\t\t\t\t\t})\n\t\t\t\t};\n\t\t\t}\n\n\t\t\tif (sourceConfig.type === 'trace') {\n\t\t\t\tconst controller = new AbortController();\n\t\t\t\treturn {\n\t\t\t\t\tcancel: () => controller.abort(),\n\t\t\t\t\tpromise: (async () => {\n\t\t\t\t\t\tconst url = `${sourceConfig.url}${sourceConfig.url.includes('?') ? '&' : '?'}_t=${Date.now()}`;\n\t\t\t\t\t\tconst response = await fetchWithTimeout(url, {\n\t\t\t\t\t\t\tcache: 'no-store',\n\t\t\t\t\t\t\tsignal: controller.signal\n\t\t\t\t\t\t});\n\n\t\t\t\t\t\tif (!response.ok) {\n\t\t\t\t\t\t\tthrow new Error(`${sourceConfig.url} HTTP ${response.status}`);\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\tconst text = await response.text();\n\t\t\t\t\t\tconst ipMatch = text.match(/^ip=(.+)$/m);\n\t\t\t\t\t\tconst requestIp = ipMatch ? ipMatch[1].trim() : '';\n\t\t\t\t\t\tif (!requestIp) {\n\t\t\t\t\t\t\tthrow new Error(`${sourceConfig.url} missing ip field`);\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\treturn {\n\t\t\t\t\t\t\tsource: sourceConfig.url,\n\t\t\t\t\t\t\trequestIp,\n\t\t\t\t\t\t\tproviderName: sourceConfig.name\n\t\t\t\t\t\t};\n\t\t\t\t\t})()\n\t\t\t\t};\n\t\t\t}\n\n\t\t\tconst controller = new AbortController();\n\t\t\treturn {\n\t\t\t\tcancel: () => controller.abort(),\n\t\t\t\tpromise: (async () => {\n\t\t\t\t\tconst url = `${sourceConfig.url}${sourceConfig.url.includes('?') ? '&' : '?'}_t=${Date.now()}`;\n\t\t\t\t\tconst response = await fetchWithTimeout(url, {\n\t\t\t\t\t\tmethod: 'HEAD',\n\t\t\t\t\t\tcache: 'no-store',\n\t\t\t\t\t\tsignal: controller.signal\n\t\t\t\t\t});\n\n\t\t\t\t\tif (!response.ok) {\n\t\t\t\t\t\tthrow new Error(`${sourceConfig.url} HTTP ${response.status}`);\n\t\t\t\t\t}\n\n\t\t\t\t\tconst requestIp = String(response.headers.get(sourceConfig.ipHeader) || '').trim();\n\t\t\t\t\tif (!requestIp) {\n\t\t\t\t\t\tthrow new Error(`${sourceConfig.url} missing ${sourceConfig.ipHeader}`);\n\t\t\t\t\t}\n\n\t\t\t\t\treturn {\n\t\t\t\t\t\tsource: sourceConfig.url,\n\t\t\t\t\t\trequestIp,\n\t\t\t\t\t\tproviderName: sourceConfig.name\n\t\t\t\t\t};\n\t\t\t\t})()\n\t\t\t};\n\t\t}\n\n\t\tasync function raceIpProbeSources(sourceConfigs, label) {\n\t\t\tif (!sourceConfigs.length) {\n\t\t\t\tthrow new Error(`${label} has no sources`);\n\t\t\t}\n\n\t\t\tconst requestTasks = sourceConfigs.map(createIpProbeRequestTask);\n\n\t\t\ttry {\n\t\t\t\treturn await Promise.any(requestTasks.map(task => task.promise));\n\t\t\t} finally {\n\t\t\t\trequestTasks.forEach(task => task.cancel && task.cancel());\n\t\t\t}\n\t\t}\n\n\t\t// 获取China Network Test数据（HEAD 优先，Failed后再用 JSONP 兜底）\n\t\tasync function fetchIpipData() {\n\t\t\tsetStatus('status-ipip', 'loading');\n\n\t\t\tconst statusElement = document.querySelector('#status-ipip');\n\t\t\tconst titleElement = statusElement ? statusElement.parentElement : null;\n\t\t\tconst testSources = [\n\t\t\t\t/*\n\t\t\t\t{\n\t\t\t\t\ttype: 'head',\n\t\t\t\t\tname: 'ByteDance / Douyin',\n\t\t\t\t\turl: 'https://perfops2.byte-test.com/500b-bench.jpg',\n\t\t\t\t\tipHeader: 'X-Request-Ip'\n\t\t\t\t},\n\t\t\t\t{\n\t\t\t\t\ttype: 'head',\n\t\t\t\t\tname: 'ByteDance / Douyin',\n\t\t\t\t\turl: 'https://perfops.byte-test.com',\n\t\t\t\t\tipHeader: 'X-Request-Ip'\n\t\t\t\t},\n\t\t\t\t{\n\t\t\t\t\ttype: 'head',\n\t\t\t\t\tname: '网易科技',\n\t\t\t\t\turl: 'https://necaptcha.nosdn.127.net/ab7f4275c1744aa28e0a8f3a1c58c532.png',\n\t\t\t\t\tipHeader: 'cdn-user-ip'\n\t\t\t\t},\n\t\t\t\t{\n\t\t\t\t\ttype: 'jsonp',\n\t\t\t\t\tname: '腾讯新闻',\n\t\t\t\t\turl: 'https://r.inews.qq.com/api/ip2city?otype=jsonp',\n\t\t\t\t\tcallbackParam: 'callback',\n\t\t\t\t\textractIp: payload => payload?.ip\n\t\t\t\t},\n\t\t\t\t{\n\t\t\t\t\ttype: 'jsonp',\n\t\t\t\t\tname: '太平洋科技',\n\t\t\t\t\turl: 'https://whois.pconline.com.cn/ipJson.jsp',\n\t\t\t\t\tcallbackParam: 'callback',\n\t\t\t\t\textractIp: payload => payload?.ip\n\t\t\t\t},\n\t\t\t\t{\n\t\t\t\t\ttype: 'jsonp',\n\t\t\t\t\tname: '阿里巴巴',\n\t\t\t\t\turl: `https://${Date.now()}.dns-detect.alicdn.com/api/detect/DescribeDNSLookup`,\n\t\t\t\t\tcallbackParam: 'cb',\n\t\t\t\t\textractIp: payload => payload?.content?.localIp\n\t\t\t\t},\n\t\t\t\t*/\n\t\t\t\t{\n\t\t\t\t\ttype: 'trace',\n\t\t\t\t\tname: 'Cloudflare China 1',\n\t\t\t\t\turl: 'https://api.cloudflare-cn.com/cdn-cgi/trace'\n\t\t\t\t},\n\t\t\t\t{\n\t\t\t\t\ttype: 'trace',\n\t\t\t\t\tname: 'Cloudflare China 2',\n\t\t\t\t\turl: 'https://www.cf-ns.com/cdn-cgi/trace'\n\t\t\t\t},\n\t\t\t\t{\n\t\t\t\t\ttype: 'trace',\n\t\t\t\t\tname: 'Cloudflare China 3',\n\t\t\t\t\turl: 'https://www.cf-ns.net/cdn-cgi/trace'\n\t\t\t\t},\n\t\t\t\t{\n\t\t\t\t\ttype: 'trace',\n\t\t\t\t\tname: 'Cloudflare China 4',\n\t\t\t\t\turl: 'https://www.cf-ns.tech/cdn-cgi/trace'\n\t\t\t\t}\n\t\t\t];\n\t\t\tconst headSources = testSources.filter(sourceConfig => sourceConfig.type === 'head' || sourceConfig.type === 'trace');\n\t\t\tconst jsonpSources = testSources.filter(sourceConfig => sourceConfig.type === 'jsonp');\n\t\t\tlet fastestSuccess;\n\t\t\ttry {\n\t\t\t\ttry {\n\t\t\t\t\tfastestSuccess = await raceIpProbeSources(headSources, 'China Network Test HEAD');\n\t\t\t\t} catch (headError) {\n\t\t\t\t\tconsole.warn('[China Network Test] HEAD 测试源Unavailable，后台切换到 JSONP 兜底:', headError);\n\t\t\t\t\tif (!jsonpSources.length) {\n\t\t\t\t\t\tthrow headError;\n\t\t\t\t\t}\n\t\t\t\t\tfastestSuccess = await raceIpProbeSources(jsonpSources, 'China Network Test JSONP');\n\t\t\t\t}\n\t\t\t} catch (error) {\n\t\t\t\tsetNetworkFieldError('ipip-ip', 'Load failed');\n\t\t\t\tclearNetworkFieldValue('ipip-country');\n\t\t\t\tapplyNetworkCardFlag('ipip-country');\n\t\t\t\tconst ipipCityElement = document.getElementById('ipip-city');\n\t\t\t\tif (ipipCityElement) {\n\t\t\t\t\tipipCityElement.textContent = '';\n\t\t\t\t}\n\t\t\t\tsetStatus('status-ipip', 'error');\n\t\t\t\tconsole.error('China Network Test 所有测试源都Failed:', error);\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\tconst fallbackIp = String(fastestSuccess.requestIp || 'Unknown').trim() || 'Unknown';\n\t\t\tsetNetworkFieldValue('ipip-ip', fallbackIp, 'ip');\n\t\t\tclearNetworkFieldValue('ipip-country');\n\t\t\tapplyNetworkCardFlag('ipip-country');\n\n\t\t\tif (titleElement) {\n\t\t\t\ttitleElement.innerHTML = `<span class=\"status-indicator\" id=\"status-ipip\"></span><div class=\"title-text\"><div class=\"title-main\">China Network Test</div><div class=\"title-subtitle\">${fastestSuccess.providerName}</div></div>`;\n\t\t\t\tsetStatus('status-ipip', 'loading');\n\t\t\t}\n\n\t\t\ttry {\n\t\t\t\tconst info = await fetchIpInfoByIp(fastestSuccess.requestIp);\n\t\t\t\tconst ip = String(info.ip || fastestSuccess.requestIp || 'Unknown').trim();\n\t\t\t\tconst location = formatIpInfoLocation(info);\n\n\t\t\t\tsetNetworkFieldValue('ipip-ip', ip, 'ip');\n\t\t\t\tsetNetworkFieldValue('ipip-country', location || 'Unknown', 'location');\n\t\t\t\tapplyNetworkCardFlag('ipip-country');\n\t\t\t\tsetStatus('status-ipip', 'success');\n\t\t\t\tconsole.log(`[China Network Test] 成功: IP=${ip}, 位置=${location}, 来源=${fastestSuccess.source}`);\n\t\t\t} catch (detailError) {\n\t\t\t\tsetNetworkFieldValue('ipip-country', 'Unknown', 'location');\n\t\t\t\tapplyNetworkCardFlag('ipip-country');\n\t\t\t\tsetStatus('status-ipip', 'success');\n\t\t\t\tconsole.warn(`[China Network Test] 已获取IP=${fallbackIp}，但查询详细信息Failed:`, detailError);\n\t\t\t}\n\t\t}\n\n\t\t// 获取International Network Test数据\n\t\tasync function fetchOverseasTestData() {\n\t\t\tsetStatus('status-overseas', 'loading');\n\t\t\t// API 配置：URL + 字段映射\n\t\t\tconst apis = [\n\t\t\t\t{\n\t\t\t\t\turl: `https://api.ipapi.is`,\n\t\t\t\t\tparse: d => ({ ip: d.ip, loc: formatIpInfoLocation(d) })\n\t\t\t\t},\n\t\t\t\t{\n\t\t\t\t\turl: `https://api.cmliussss.net/api/ipinfo`,\n\t\t\t\t\tparse: d => ({ ip: d.ip, loc: formatIpInfoLocation(d) })\n\t\t\t\t}\n\t\t\t];\n\n\t\t\tconst requestTasks = apis.map(api => {\n\t\t\t\tconst controller = new AbortController();\n\t\t\t\treturn {\n\t\t\t\t\tcancel: () => controller.abort(),\n\t\t\t\t\tpromise: (async () => {\n\t\t\t\t\t\tconst url = `${api.url}${api.url.includes('?') ? '&' : '?'}_t=${Date.now()}`;\n\t\t\t\t\t\tconst response = await fetchWithTimeout(url, {\n\t\t\t\t\t\t\tcache: 'no-store',\n\t\t\t\t\t\t\tsignal: controller.signal\n\t\t\t\t\t\t});\n\t\t\t\t\t\tif (!response.ok) throw new Error(`HTTP ${response.status}`);\n\t\t\t\t\t\tconst { ip, loc } = api.parse(await response.json());\n\t\t\t\t\t\tconst edgeIp = ip || 'Unknown';\n\n\t\t\t\t\t\treturn { edgeIp, loc, url: api.url };\n\t\t\t\t\t})().catch(error => {\n\t\t\t\t\t\tconsole.log(`[International Network Test] ${api.url} Failed: ${error.message}`);\n\t\t\t\t\t\tthrow error;\n\t\t\t\t\t})\n\t\t\t\t};\n\t\t\t});\n\n\t\t\ttry {\n\t\t\t\tconst { edgeIp, loc } = await Promise.any(requestTasks.map(task => task.promise));\n\t\t\t\trequestTasks.forEach(task => task.cancel && task.cancel());\n\t\t\t\tsetNetworkFieldValue('overseas-ip', edgeIp, 'ip');\n\t\t\t\tsetNetworkFieldValue('overseas-country', loc || 'Unknown', 'location');\n\t\t\t\tapplyNetworkCardFlag('overseas-country');\n\t\t\t\tsetStatus('status-overseas', 'success');\n\t\t\t\tconsole.log(`[International Network Test] 成功: IP=${edgeIp}, 位置=${loc}`);\n\t\t\t\treturn;\n\t\t\t} catch (error) {\n\t\t\t\trequestTasks.forEach(task => task.cancel && task.cancel());\n\t\t\t}\n\n\t\t\t// 所有 API 都Failed\n\t\t\tsetNetworkFieldError('overseas-ip', 'Load failed');\n\t\t\tclearNetworkFieldValue('overseas-country');\n\t\t\tapplyNetworkCardFlag('overseas-country');\n\t\t\tsetStatus('status-overseas', 'error');\n\t\t\tconsole.error('International Network Test 所有API都Failed');\n\t\t}\n\n\t\t// CloudFlare ProxyIP 卡片状态（支持双出口切换）\n\t\tlet cloudFlareEntries = [];\n\t\tlet cloudFlareActiveIndex = 0;\n\n\t\t// Overseas Site Test卡片状态（支持多来源切换）\n\t\tlet twitterEntries = [];\n\t\tlet twitterActiveIndex = 0;\n\n\t\tfunction isValidIpv4(ip) {\n\t\t\tconst value = String(ip || '').trim();\n\t\t\tif (!/^\\d{1,3}(\\.\\d{1,3}){3}$/.test(value)) return false;\n\t\t\treturn value.split('.').every(part => {\n\t\t\t\tif (!/^\\d+$/.test(part)) return false;\n\t\t\t\tconst num = Number(part);\n\t\t\t\treturn num >= 0 && num <= 255;\n\t\t\t});\n\t\t}\n\n\t\tfunction isValidIpv6(ip) {\n\t\t\tconst value = String(ip || '').trim().replace(/^\\[|\\]$/g, '');\n\t\t\tif (!value || !value.includes(':')) return false;\n\t\t\ttry {\n\t\t\t\t// 借助 URL 解析器校验 IPv6 格式，兼容缩写写法\n\t\t\t\tnew URL(`http://[${value}]/`);\n\t\t\t\treturn true;\n\t\t\t} catch {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t}\n\n\t\tfunction detectIpVersion(ip) {\n\t\t\tconst value = String(ip || '').trim();\n\t\t\tif (!value) return '';\n\t\t\tif (isValidIpv4(value)) return 'v4';\n\t\t\tif (isValidIpv6(value)) return 'v6';\n\t\t\treturn '';\n\t\t}\n\n\t\tfunction getCloudFlareProxyClass(version) {\n\t\t\tif (version === 'v4') return 'cf-subtitle-v4';\n\t\t\tif (version === 'v6') return 'cf-subtitle-v6';\n\t\t\treturn '';\n\t\t}\n\n\t\tfunction getCloudFlareProxyLabel(version, full = false) {\n\t\t\tif (version === 'v4') return full ? 'ProxyIPv4' : 'v4';\n\t\t\tif (version === 'v6') return full ? 'ProxyIPv6' : 'v6';\n\t\t\treturn full ? 'ProxyIP' : 'IP';\n\t\t}\n\n\t\tfunction formatCloudFlareLocation(data) {\n\t\t\tconst country = String(data?.country || '').trim();\n\t\t\tconst org = String(data?.org || '').trim();\n\t\t\treturn `${country} ${org}`.trim() || 'Unknown';\n\t\t}\n\n\t\tfunction resetCloudFlareSubtitle() {\n\t\t\tconst subtitleElement = document.getElementById('cf-subtitle');\n\t\t\tif (!subtitleElement) return;\n\t\t\tsubtitleElement.classList.remove('cf-subtitle-rich');\n\t\t\tsubtitleElement.textContent = 'ProxyIP';\n\t\t}\n\n\t\tfunction renderCloudFlareSubtitle() {\n\t\t\tconst subtitleElement = document.getElementById('cf-subtitle');\n\t\t\tif (!subtitleElement) return;\n\n\t\t\tif (!cloudFlareEntries.length) {\n\t\t\t\tresetCloudFlareSubtitle();\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\tsubtitleElement.classList.add('cf-subtitle-rich');\n\n\t\t\tif (cloudFlareEntries.length === 1) {\n\t\t\t\tconst entry = cloudFlareEntries[0];\n\t\t\t\tsubtitleElement.innerHTML = `<span class=\"${getCloudFlareProxyClass(entry.version)}\">${getCloudFlareProxyLabel(entry.version, true)}</span>`;\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\tcloudFlareActiveIndex = Math.min(Math.max(cloudFlareActiveIndex, 0), cloudFlareEntries.length - 1);\n\t\t\tconst onSwitch = event => {\n\t\t\t\tevent.preventDefault();\n\t\t\t\tevent.stopPropagation();\n\t\t\t\tconst targetIndex = Number(event.currentTarget.dataset.cfTargetIndex);\n\t\t\t\tif (!Number.isInteger(targetIndex)) return;\n\t\t\t\tif (targetIndex < 0 || targetIndex >= cloudFlareEntries.length) return;\n\t\t\t\tif (targetIndex === cloudFlareActiveIndex) return;\n\n\t\t\t\tcloudFlareActiveIndex = targetIndex;\n\t\t\t\trenderCloudFlareActiveEntry();\n\t\t\t};\n\n\t\t\tconst subtitleHtml = cloudFlareEntries.map((entry, index) => {\n\t\t\t\tconst entryClass = getCloudFlareProxyClass(entry.version);\n\t\t\t\tconst isActive = index === cloudFlareActiveIndex;\n\t\t\t\tconst label = getCloudFlareProxyLabel(entry.version, isActive);\n\t\t\t\tif (isActive) {\n\t\t\t\t\treturn `<span class=\"${entryClass}\">${label}</span>`;\n\t\t\t\t}\n\n\t\t\t\treturn `<span class=\"${entryClass} cf-subtitle-switch\" data-cf-target-index=\"${index}\" role=\"button\" tabindex=\"0\">${label}</span>`;\n\t\t\t}).join('<span class=\"cf-subtitle-sep\"> / </span>');\n\n\t\t\tsubtitleElement.innerHTML = subtitleHtml;\n\n\t\t\tconst switchElements = subtitleElement.querySelectorAll('.cf-subtitle-switch');\n\t\t\tswitchElements.forEach(switchElement => {\n\t\t\t\tswitchElement.title = 'Click to switch egress IP';\n\t\t\t\tswitchElement.addEventListener('click', onSwitch);\n\t\t\t\tswitchElement.addEventListener('keydown', event => {\n\t\t\t\t\tif (event.key !== 'Enter' && event.key !== ' ') return;\n\t\t\t\t\tonSwitch(event);\n\t\t\t\t});\n\t\t\t});\n\t\t}\n\n\t\tfunction renderCloudFlareActiveEntry() {\n\t\t\tif (!cloudFlareEntries.length) return;\n\t\t\tcloudFlareActiveIndex = Math.min(Math.max(cloudFlareActiveIndex, 0), cloudFlareEntries.length - 1);\n\n\t\t\tconst activeEntry = cloudFlareEntries[cloudFlareActiveIndex];\n\t\t\tsetNetworkFieldValue('cf-ip', activeEntry.ip, 'ip');\n\t\t\tsetNetworkFieldValue('cf-country', activeEntry.loc || 'Unknown', 'location');\n\t\t\tapplyNetworkCardFlag('cf-country');\n\t\t\trenderCloudFlareSubtitle();\n\t\t}\n\n\t\t// 获取 CloudFlare 数据（并发请求多个接口，按实际返回 IP 判定类型）\n\t\tasync function fetchCloudFlareData() {\n\t\t\tsetStatus('status-cf', 'loading');\n\t\t\tcloudFlareEntries = [];\n\t\t\tcloudFlareActiveIndex = 0;\n\t\t\tresetCloudFlareSubtitle();\n\n\t\t\tconst timestamp = Date.now();\n\t\t\tconst endpoints = [\n\t\t\t\t{ url: 'https://ipv4.090227.xyz' },\n\t\t\t\t{ url: 'https://ipv6.090227.xyz' }\n\t\t\t];\n\n\t\t\ttry {\n\t\t\t\tconst requestResults = await Promise.allSettled(\n\t\t\t\t\tendpoints.map(async endpoint => {\n\t\t\t\t\t\tconst response = await fetchWithTimeout(`${endpoint.url}/?_t=${timestamp}`, { cache: 'no-store' });\n\t\t\t\t\t\tif (!response.ok) {\n\t\t\t\t\t\t\tthrow new Error(`HTTP ${response.status}`);\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\tconst data = await response.json();\n\t\t\t\t\t\tconst ip = String(data?.ip || '').trim();\n\t\t\t\t\t\tconst version = detectIpVersion(ip);\n\t\t\t\t\t\tif (!ip || !version) {\n\t\t\t\t\t\t\tthrow new Error(`invalid ip payload: ${ip || 'empty'}`);\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\treturn {\n\t\t\t\t\t\t\tip,\n\t\t\t\t\t\t\tversion,\n\t\t\t\t\t\t\tloc: formatCloudFlareLocation(data)\n\t\t\t\t\t\t};\n\t\t\t\t\t})\n\t\t\t\t);\n\n\t\t\t\tconst availableEntries = [];\n\t\t\t\tconst seenEntryKeys = new Set();\n\n\t\t\t\trequestResults.forEach((result, index) => {\n\t\t\t\t\tconst endpoint = endpoints[index];\n\t\t\t\t\tif (result.status !== 'fulfilled') {\n\t\t\t\t\t\tconst reason = result.reason?.message || String(result.reason || 'unknown error');\n\t\t\t\t\t\tconsole.log(`[CloudFlare] ${endpoint.url} Failed: ${reason}`);\n\t\t\t\t\t\treturn;\n\t\t\t\t\t}\n\n\t\t\t\t\tconst entry = result.value;\n\t\t\t\t\tif (!entry?.ip || !entry?.version) return;\n\t\t\t\t\tconst normalizedIp = String(entry.ip || '').trim().toLowerCase();\n\t\t\t\t\tconst dedupeKey = `${entry.version}:${normalizedIp}`;\n\t\t\t\t\tif (seenEntryKeys.has(dedupeKey)) {\n\t\t\t\t\t\treturn;\n\t\t\t\t\t}\n\t\t\t\t\tseenEntryKeys.add(dedupeKey);\n\t\t\t\t\tavailableEntries.push(entry);\n\t\t\t\t});\n\n\t\t\t\tif (!availableEntries.length) {\n\t\t\t\t\tthrow new Error('no valid cloudflare ip from all endpoints');\n\t\t\t\t}\n\n\t\t\t\tconst hasV4 = availableEntries.some(entry => entry.version === 'v4');\n\t\t\t\tconst hasV6 = availableEntries.some(entry => entry.version === 'v6');\n\t\t\t\tif (hasV4 && hasV6) {\n\t\t\t\t\tavailableEntries.sort((a, b) => {\n\t\t\t\t\t\tif (a.version === b.version) return 0;\n\t\t\t\t\t\treturn a.version === 'v4' ? -1 : 1;\n\t\t\t\t\t});\n\t\t\t\t}\n\n\t\t\t\tcloudFlareEntries = availableEntries;\n\t\t\t\tcloudFlareActiveIndex = 0;\n\t\t\t\trenderCloudFlareActiveEntry();\n\t\t\t\tsetStatus('status-cf', 'success');\n\n\t\t\t\tconst summary = cloudFlareEntries.map(entry => `${entry.ip}(${entry.version})`).join(', ');\n\t\t\t\tconsole.log(`[CloudFlare] 成功: ${summary}`);\n\t\t\t} catch (error) {\n\t\t\t\tsetNetworkFieldError('cf-ip', 'Load failed');\n\t\t\t\tclearNetworkFieldValue('cf-country');\n\t\t\t\tapplyNetworkCardFlag('cf-country');\n\t\t\t\tresetCloudFlareSubtitle();\n\t\t\t\tsetStatus('status-cf', 'error');\n\t\t\t\tconsole.error('CloudFlare 接口错误:', error);\n\t\t\t}\n\t\t}\n\n\t\t// 获取Overseas Site Test数据（后台并发取最快可用源）\n\t\t// 获取Overseas Site Test数据（后台并发取所有可用源，支持切换显示）\n\t\tasync function fetchTwitterData() {\n\t\t\tsetStatus('status-twitter', 'loading');\n\t\t\tconst statusElement = document.querySelector('#status-twitter');\n\t\t\tconst titleElement = statusElement ? statusElement.parentElement : null;\n\t\t\tconst tipElement = document.getElementById('twitter-tip');\n\t\t\tconst isInvalidOutsideEntryIp = ip => {\n\t\t\t\tconst candidate = String(ip || '').trim();\n\t\t\t\treturn !candidate || candidate === '0.0.0.0';\n\t\t\t};\n\n\t\t\tconst renderTwitterSubtitle = () => {\n\t\t\t\tif (!titleElement) return;\n\t\t\t\tconst prevIndicator = document.getElementById('status-twitter');\n\t\t\t\tconst prevStatus = prevIndicator ? (prevIndicator.className.match(/status-(?!indicator)(\\w+)/) || [])[1] : '';\n\t\t\t\tconst getBrandClass = name => {\n\t\t\t\t\tif (name.includes('Google')) return 'tw-subtitle-google';\n\t\t\t\t\tif (name.includes('X.com')) return 'tw-subtitle-twitter';\n\t\t\t\t\treturn '';\n\t\t\t\t};\n\t\t\t\tif (!twitterEntries.length) {\n\t\t\t\t\ttitleElement.innerHTML = '<span class=\"status-indicator\" id=\"status-twitter\"></span><div class=\"title-text\"><div class=\"title-main\">Overseas Site Test</div><div class=\"title-subtitle\">!CN-Test</div></div>';\n\t\t\t\t\tif (prevStatus) setStatus('status-twitter', prevStatus);\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tif (twitterEntries.length === 1) {\n\t\t\t\t\tconst brandClass = getBrandClass(twitterEntries[0].providerName);\n\t\t\t\t\ttitleElement.innerHTML = `<span class=\"status-indicator\" id=\"status-twitter\"></span><div class=\"title-text\"><div class=\"title-main\">Overseas Site Test</div><div class=\"title-subtitle\"><span class=\"${brandClass}\">${twitterEntries[0].providerName}</span></div></div>`;\n\t\t\t\t\tif (prevStatus) setStatus('status-twitter', prevStatus);\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\ttwitterActiveIndex = Math.min(Math.max(twitterActiveIndex, 0), twitterEntries.length - 1);\n\t\t\t\tconst onSwitch = event => {\n\t\t\t\t\tevent.preventDefault();\n\t\t\t\t\tevent.stopPropagation();\n\t\t\t\t\tconst targetIndex = Number(event.currentTarget.dataset.twTargetIndex);\n\t\t\t\t\tif (!Number.isInteger(targetIndex)) return;\n\t\t\t\t\tif (targetIndex < 0 || targetIndex >= twitterEntries.length) return;\n\t\t\t\t\tif (targetIndex === twitterActiveIndex) return;\n\t\t\t\t\ttwitterActiveIndex = targetIndex;\n\t\t\t\t\trenderTwitterActiveEntry();\n\t\t\t\t};\n\t\t\t\tconst subtitleHtml = twitterEntries.map((entry, index) => {\n\t\t\t\t\tconst isActive = index === twitterActiveIndex;\n\t\t\t\t\tconst label = entry.providerName;\n\t\t\t\t\tconst brandClass = getBrandClass(label);\n\t\t\t\t\tif (isActive) {\n\t\t\t\t\t\treturn `<span class=\"${brandClass}\">${label}</span>`;\n\t\t\t\t\t}\n\t\t\t\t\treturn `<span class=\"${brandClass} cf-subtitle-switch\" data-tw-target-index=\"${index}\" role=\"button\" tabindex=\"0\">${label}</span>`;\n\t\t\t\t}).join('<span class=\"cf-subtitle-sep\"> / </span>');\n\t\t\t\ttitleElement.innerHTML = `<span class=\"status-indicator\" id=\"status-twitter\"></span><div class=\"title-text\"><div class=\"title-main\">Overseas Site Test</div><div class=\"title-subtitle\">${subtitleHtml}</div></div>`;\n\t\t\t\tif (prevStatus) setStatus('status-twitter', prevStatus);\n\t\t\t\tconst switchElements = titleElement.querySelectorAll('.cf-subtitle-switch');\n\t\t\t\tswitchElements.forEach(el => {\n\t\t\t\t\tel.title = 'Click to switch source';\n\t\t\t\t\tel.addEventListener('click', onSwitch);\n\t\t\t\t\tel.addEventListener('keydown', event => {\n\t\t\t\t\t\tif (event.key !== 'Enter' && event.key !== ' ') return;\n\t\t\t\t\t\tonSwitch(event);\n\t\t\t\t\t});\n\t\t\t\t});\n\t\t\t};\n\n\t\t\tconst renderTwitterActiveEntry = () => {\n\t\t\t\tif (!twitterEntries.length) return;\n\t\t\t\ttwitterActiveIndex = Math.min(Math.max(twitterActiveIndex, 0), twitterEntries.length - 1);\n\t\t\t\tconst activeEntry = twitterEntries[twitterActiveIndex];\n\t\t\t\tsetNetworkFieldValue('twitter-ip', activeEntry.ip, 'ip');\n\t\t\t\tsetNetworkFieldValue('twitter-country', activeEntry.loc || 'Unknown', 'location');\n\t\t\t\tapplyNetworkCardFlag('twitter-country');\n\t\t\t\tif (tipElement) {\n\t\t\t\t\ttipElement.textContent = `· IP used to access ${activeEntry.providerName}`;\n\t\t\t\t}\n\t\t\t\trenderTwitterSubtitle();\n\t\t\t};\n\n\t\t\tconst renderTwitterTip = (sourceName) => {\n\t\t\t\tif (!tipElement) return;\n\t\t\t\ttipElement.textContent = `· IP used to access ${sourceName}`;\n\t\t\t};\n\n\t\t\tconst testSources = [\n\t\t\t\t{\n\t\t\t\t\tname: 'Google',\n\t\t\t\t\tcreateTask: () => {\n\t\t\t\t\t\tconst jsonpTask = createJsonpRequest(`https://jsonp-ip.appspot.com/?_t=${Date.now()}`, 'callback');\n\t\t\t\t\t\treturn {\n\t\t\t\t\t\t\tcancel: jsonpTask.cancel,\n\t\t\t\t\t\t\tpromise: jsonpTask.promise.then(payload => {\n\t\t\t\t\t\t\t\tconst requestIp = String(payload?.ip || '').trim();\n\t\t\t\t\t\t\t\tif (isInvalidOutsideEntryIp(requestIp)) {\n\t\t\t\t\t\t\t\t\tif (requestIp === '0.0.0.0') {\n\t\t\t\t\t\t\t\t\t\tthrow new Error('google jsonp returned invalid ip 0.0.0.0');\n\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\tthrow new Error('google jsonp missing ip');\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\treturn {\n\t\t\t\t\t\t\t\t\tproviderName: 'Google',\n\t\t\t\t\t\t\t\t\trequestIp\n\t\t\t\t\t\t\t\t};\n\t\t\t\t\t\t\t})\n\t\t\t\t\t\t};\n\t\t\t\t\t}\n\t\t\t\t},\n\t\t\t\t{\n\t\t\t\t\tname: 'X (formerly Twitter)',\n\t\t\t\t\tcreateTask: () => {\n\t\t\t\t\t\tconst controller = new AbortController();\n\t\t\t\t\t\treturn {\n\t\t\t\t\t\t\tcancel: () => controller.abort(),\n\t\t\t\t\t\t\tpromise: (async () => {\n\t\t\t\t\t\t\t\tconst response = await fetchWithTimeout(`https://help.x.com/cdn-cgi/trace?_t=${Date.now()}`, {\n\t\t\t\t\t\t\t\t\tcache: 'no-store',\n\t\t\t\t\t\t\t\t\tsignal: controller.signal\n\t\t\t\t\t\t\t\t});\n\t\t\t\t\t\t\t\tif (!response.ok) {\n\t\t\t\t\t\t\t\t\tthrow new Error(`x trace HTTP ${response.status}`);\n\t\t\t\t\t\t\t\t}\n\n\t\t\t\t\t\t\t\tconst text = await response.text();\n\t\t\t\t\t\t\t\tconst ipLine = text.split('\\n').find(line => line.startsWith('ip='));\n\t\t\t\t\t\t\t\tconst requestIp = String(ipLine ? ipLine.slice(3) : '').trim();\n\t\t\t\t\t\t\t\tif (isInvalidOutsideEntryIp(requestIp)) {\n\t\t\t\t\t\t\t\t\tif (requestIp === '0.0.0.0') {\n\t\t\t\t\t\t\t\t\t\tthrow new Error('x trace returned invalid ip 0.0.0.0');\n\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\tthrow new Error('x trace missing ip');\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\treturn {\n\t\t\t\t\t\t\t\t\tproviderName: 'X (formerly Twitter)',\n\t\t\t\t\t\t\t\t\trequestIp\n\t\t\t\t\t\t\t\t};\n\t\t\t\t\t\t\t})()\n\t\t\t\t\t\t};\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t];\n\n\t\t\ttwitterEntries = [];\n\t\t\ttwitterActiveIndex = 0;\n\n\t\t\ttry {\n\t\t\t\tconst requestTasks = testSources.map(source => {\n\t\t\t\t\tconst task = source.createTask();\n\t\t\t\t\tconst taskPromise = task.promise.then(result => {\n\t\t\t\t\t\treturn { source: source.name, result };\n\t\t\t\t\t}).catch(sourceError => {\n\t\t\t\t\t\tconsole.log(`[Overseas Site Test] ${source.name} Failed: ${sourceError.message}`);\n\t\t\t\t\t\treturn { source: source.name, error: sourceError };\n\t\t\t\t\t});\n\t\t\t\t\treturn { cancel: task.cancel, promise: taskPromise };\n\t\t\t\t});\n\n\t\t\t\t// 等所有来源完成（不再Cancel慢的那个）\n\t\t\t\tconst results = await Promise.allSettled(requestTasks.map(t => t.promise));\n\n\t\t\t\tconst successfulResults = [];\n\t\t\t\tfor (const settled of results) {\n\t\t\t\t\tif (settled.status === 'fulfilled' && settled.value && settled.value.result) {\n\t\t\t\t\t\tsuccessfulResults.push(settled.value);\n\t\t\t\t\t}\n\t\t\t\t}\n\n\t\t\t\tif (!successfulResults.length) {\n\t\t\t\t\tthrow new Error('all outside entry sources failed');\n\t\t\t\t}\n\n\t\t\t\t// enable it for每个成功的来源查询 IP Details\n\t\t\t\tconst detailPromises = successfulResults.map(async ({ source, result }) => {\n\t\t\t\t\ttry {\n\t\t\t\t\t\tconst info = await fetchIpInfoByIp(result.requestIp);\n\t\t\t\t\t\treturn {\n\t\t\t\t\t\t\tproviderName: result.providerName,\n\t\t\t\t\t\t\tip: String(info.ip || result.requestIp || 'Unknown').trim(),\n\t\t\t\t\t\t\tloc: formatIpInfoLocation(info)\n\t\t\t\t\t\t};\n\t\t\t\t\t} catch {\n\t\t\t\t\t\treturn {\n\t\t\t\t\t\t\tproviderName: result.providerName,\n\t\t\t\t\t\t\tip: String(result.requestIp || 'Unknown').trim(),\n\t\t\t\t\t\t\tloc: 'Unknown'\n\t\t\t\t\t\t};\n\t\t\t\t\t}\n\t\t\t\t});\n\n\t\t\t\tconst detailedEntries = await Promise.all(detailPromises);\n\t\t\t\ttwitterEntries = detailedEntries;\n\t\t\t\ttwitterActiveIndex = 0;\n\n\t\t\t\t// 渲染第一个（默认选中第一个）\n\t\t\t\trenderTwitterActiveEntry();\n\t\t\t\tsetStatus('status-twitter', 'success');\n\n\t\t\t\tconst summary = twitterEntries.map(e => `${e.ip}(${e.providerName})`).join(', ');\n\t\t\t\tconsole.log(`[Overseas Site Test] 成功: ${summary}`);\n\t\t\t} catch (error) {\n\t\t\t\tsetNetworkFieldError('twitter-ip', 'Access unavailable');\n\t\t\t\tclearNetworkFieldValue('twitter-country');\n\t\t\t\tapplyNetworkCardFlag('twitter-country');\n\t\t\t\tif (titleElement) {\n\t\t\t\t\ttitleElement.innerHTML = '<span class=\"status-indicator\" id=\"status-twitter\"></span><div class=\"title-text\"><div class=\"title-main\">Overseas Site Test</div><div class=\"title-subtitle\">Access failed</div></div>';\n\t\t\t\t}\n\t\t\t\tsetStatus('status-twitter', 'error');\n\t\t\t\trenderTwitterTip('overseas sites');\n\t\t\t\tconsole.error('Overseas Site Test接口错误:', error);\n\t\t\t}\n\t\t}\n\t\t// 网络信息加载标志\n\t\tlet networkInfoLoaded = false;\n\n\t\t// 加载网络信息\n\t\tasync function loadNetworkInfo() {\n\t\t\tif (networkInfoLoadPromise) {\n\t\t\t\treturn networkInfoLoadPromise;\n\t\t\t}\n\n\t\t\t// 检查容器是否存In\n\t\t\tconst container = document.querySelector('.network-cards-container');\n\t\t\tif (!container) return;\n\t\t\tbindNetworkCardPrivacyToggle();\n\n\t\t\t// 设置加载标志\n\t\t\tnetworkInfoLoaded = true;\n\n\t\t\tconst networkTasks = [\n\t\t\t\t{ name: 'International Network Test', run: fetchOverseasTestData },\n\t\t\t\t{ name: 'CloudFlare', run: fetchCloudFlareData },\n\t\t\t\t{ name: 'China Network Test', run: fetchIpipData },\n\t\t\t\t{ name: 'Overseas Site Test', run: fetchTwitterData }\n\t\t\t];\n\n\t\t\tnetworkInfoLoadPromise = (async () => {\n\t\t\t\tfor (let i = 0; i < networkTasks.length; i++) {\n\t\t\t\t\tawait runNetworkInfoBackgroundTask(networkTasks[i], i);\n\t\t\t\t}\n\n\t\t\t\t// 所有网络信息加载完成后,使 IP 可点击\n\t\t\t\tsetTimeout(() => {\n\t\t\t\t\tmakeIpClickable();\n\t\t\t\t}, 500);\n\t\t\t})();\n\n\t\t\treturn networkInfoLoadPromise;\n\t\t}\n\n\t\t// 页面加载完成并进入空闲状态后，In后台获取网络信息，避免影响前台初始化\n\t\tscheduleNetworkInfoLoad();\n\n\t\t// IP 点击查询Details功能\n\t\tfunction makeIpClickable() {\n\t\t\tconst ipElements = document.querySelectorAll('.ip-text');\n\n\t\t\tipElements.forEach(element => {\n\t\t\t\tconst rawIpText = String(element.dataset.rawValue || element.textContent || '').trim();\n\n\t\t\t\t// 跳过已经标记enable it for错误、加载中、Unknown的元素\n\t\t\t\tif (element.querySelector('.error') ||\n\t\t\t\t\telement.dataset.displayState === 'error' ||\n\t\t\t\t\trawIpText === 'Loading...' ||\n\t\t\t\t\trawIpText === 'Unknown' ||\n\t\t\t\t\t!rawIpText ||\n\t\t\t\t\telement.classList.contains('clickable')) {\n\t\t\t\t\treturn;\n\t\t\t\t}\n\n\t\t\t\t// 添加可点击样式\n\t\t\t\telement.classList.add('clickable');\n\t\t\t\telement.title = 'Click to view detailed IP information';\n\n\t\t\t\telement.addEventListener('click', function (event) {\n\t\t\t\t\tevent.stopPropagation();\n\n\t\t\t\t\tif (this.dataset.displayState !== 'ready') {\n\t\t\t\t\t\treturn;\n\t\t\t\t\t}\n\n\t\t\t\t\tconst rawIp = String(this.dataset.rawValue || this.textContent || '').trim();\n\n\t\t\t\t\t// 跳过显示\"Loading...\"或\"Unknown\"的元素\n\t\t\t\t\tif (!rawIp || rawIp === 'Loading...' || rawIp === 'Unknown') {\n\t\t\t\t\t\treturn;\n\t\t\t\t\t}\n\n\t\t\t\t\tfetchAndShowIpDetail(rawIp, this);\n\t\t\t\t});\n\t\t\t});\n\t\t}\n\n\t\t// 将布尔值转换enable it for emoji\n\t\tfunction boolToEmoji(value, trueEmoji = '✅', falseEmoji = '❌') {\n\t\t\treturn value ? trueEmoji : falseEmoji;\n\t\t}\n\n\t\t// 将 IP 类型转换enable it for中文并添加样式\n\t\tfunction formatIpType(type) {\n\t\t\tif (!type) return '<span class=\"ip-type-unknown\">Unknown</span>';\n\n\t\t\tconst typeMap = {\n\t\t\t\t'isp': { text: '住宅', class: 'ip-type-residential' },\n\t\t\t\t'hosting': { text: '机房', class: 'ip-type-hosting' },\n\t\t\t\t'business': { text: '商用', class: 'ip-type-business' }\n\t\t\t};\n\n\t\t\tconst typeInfo = typeMap[type.toLowerCase()] || { text: type, class: 'ip-type-unknown' };\n\t\t\treturn `<span class=\"${typeInfo.class}\">${typeInfo.text}</span>`;\n\t\t}\n\n\t\t// 获取威胁等级的样式类\n\t\tfunction getThreatBadgeClass(score) {\n\t\t\tif (!score) return 'badge-info';\n\n\t\t\tconst numScore = parseFloat(score);\n\t\t\tif (numScore < 0.001) return 'badge-success';\n\t\t\tif (numScore < 0.01) return 'badge-info';\n\t\t\tif (numScore < 0.1) return 'badge-warning';\n\t\t\treturn 'badge-danger';\n\t\t}\n\n\t\t// 计算综合滥用评m\n\t\tfunction calculateAbuseScore(companyScore, asnScore, securityFlags = {}) {\n\t\t\t// 如果两个m数都None效，返回null\n\t\t\tif (!companyScore || companyScore === 'Unknown') companyScore = 0;\n\t\t\tif (!asnScore || asnScore === 'Unknown') asnScore = 0;\n\n\t\t\tconst company = parseFloat(companyScore) || 0;\n\t\t\tconst asn = parseFloat(asnScore) || 0;\n\n\t\t\t// 计算基础评m：(company + asn) / 2 * 5\n\t\t\tlet baseScore = ((company + asn) / 2) * 5;\n\n\t\t\t// 计算安全风险附加m：每个安全风险项增加 15%\n\t\t\tlet riskAddition = 0;\n\t\t\tconst riskFlags = [\n\t\t\t\tsecurityFlags.is_crawler,   // 爬虫\n\t\t\t\tsecurityFlags.is_proxy,     // Proxy server\n\t\t\t\tsecurityFlags.is_vpn,       // VPN\n\t\t\t\tsecurityFlags.is_tor,       // Tor 网络\n\t\t\t\tsecurityFlags.is_abuser     // 滥用 IP\n\t\t\t];\n\n\t\t\t// 统计enable it for true 的风险项数量\n\t\t\tconst riskCount = riskFlags.filter(flag => flag === true).length;\n\t\t\triskAddition = riskCount * 0.15; // 每个风险项增加 15%\n\n\t\t\t// 最终评m = 基础评m + 风险附加m\n\t\t\tlet finalScore = baseScore + riskAddition;\n\n\t\t\t// 如果是虚假IP (蜜罐)，则风险值增加100%\n\t\t\tif (securityFlags.is_bogon === true) {\n\t\t\t\tfinalScore += 1.0; // 增加100%\n\t\t\t}\n\n\t\t\t// 如果基础评m和风险附加m都是0且不是虚假IP，返回null\n\t\t\tif (baseScore === 0 && riskAddition === 0 && securityFlags.is_bogon !== true) return null;\n\n\t\t\treturn finalScore;\n\t\t}\n\n\t\t// 获取滥用评m的颜色等级\n\t\tfunction getAbuseScoreBadgeClass(percentage) {\n\t\t\tif (percentage === null || percentage === undefined) return 'badge-info';\n\n\t\t\tif (percentage >= 100) return 'badge-critical';      // 危险红色 >= 100%\n\t\t\tif (percentage >= 20) return 'badge-high';           // 橘黄色 15-99.99%\n\t\t\tif (percentage >= 5) return 'badge-elevated';     // 黄色 5-14.99%\n\t\t\tif (percentage >= 0.25) return 'badge-low';          // 淡绿色 0.25-4.99%\n\t\t\treturn 'badge-verylow';                              // 绿色 < 0.25%\n\t\t}\n\n\t\t// 格式化滥用评menable it for百m比\n\t\tfunction formatAbuseScorePercentage(score) {\n\t\t\tif (score === null || score === undefined) return 'Unknown';\n\n\t\t\tconst percentage = score * 100;\n\t\t\treturn percentage.toFixed(2) + '%';\n\t\t}\n\n\t\t// 切换评m算法This means气泡\n\t\tfunction toggleScoreTooltip(helpIcon) {\n\t\t\tconst tooltip = helpIcon.nextElementSibling;\n\t\t\tconst isShowing = tooltip.classList.contains('show');\n\n\t\t\t// 隐藏所有其他气泡\n\t\t\tdocument.querySelectorAll('.score-tooltip.show').forEach(t => {\n\t\t\t\tif (t !== tooltip) t.classList.remove('show');\n\t\t\t});\n\n\t\t\t// 切换当前气泡\n\t\t\ttooltip.classList.toggle('show');\n\n\t\t\t// 如果显示气泡，调整位置并添加点击事件监听器来Off它\n\t\t\tif (!isShowing) {\n\t\t\t\tsetTimeout(() => {\n\t\t\t\t\tpositionTooltipNearMouse(tooltip, helpIcon);\n\n\t\t\t\t\tconst closeTooltip = (e) => {\n\t\t\t\t\t\tif (!tooltip.contains(e.target) && !helpIcon.contains(e.target)) {\n\t\t\t\t\t\t\ttooltip.classList.remove('show');\n\t\t\t\t\t\t\tdocument.removeEventListener('click', closeTooltip);\n\t\t\t\t\t\t}\n\t\t\t\t\t};\n\t\t\t\t\tdocument.addEventListener('click', closeTooltip);\n\t\t\t\t}, 100);\n\t\t\t}\n\t\t}\n\n\t\t// 将气泡位置设置In鼠标附近\n\t\tfunction positionTooltipNearMouse(tooltip, helpIcon) {\n\t\t\tconst iconRect = helpIcon.getBoundingClientRect();\n\t\t\tconst tooltipWidth = tooltip.offsetWidth;\n\t\t\tconst tooltipHeight = tooltip.offsetHeight;\n\t\t\tconst windowWidth = window.innerWidth;\n\t\t\tconst windowHeight = window.innerHeight;\n\t\t\tconst padding = 10;\n\n\t\t\tlet left = iconRect.right + padding;\n\t\t\tlet top = iconRect.top - tooltipHeight / 2;\n\n\t\t\t// 如果气泡超出右边界，显示In左边\n\t\t\tif (left + tooltipWidth > windowWidth - padding) {\n\t\t\t\tleft = iconRect.left - tooltipWidth - padding;\n\t\t\t}\n\n\t\t\t// 如果气泡超出顶部，调整到下方\n\t\t\tif (top < padding) {\n\t\t\t\ttop = iconRect.top + padding;\n\t\t\t}\n\n\t\t\t// 如果气泡超出底部，调整到上方\n\t\t\tif (top + tooltipHeight > windowHeight - padding) {\n\t\t\t\ttop = windowHeight - tooltipHeight - padding;\n\t\t\t}\n\n\t\t\ttooltip.style.position = 'fixed';\n\t\t\ttooltip.style.left = left + 'px';\n\t\t\ttooltip.style.top = top + 'px';\n\t\t}\n\n\t\t// 将 ipapi.is 新版扁平响应归一化enable it for旧版嵌套结构（幂等：已含 location 子对象的旧格式/fallback 数据原样返回）\n\t\tfunction normalizeIpapiData(data) {\n\t\t\tif (!data || typeof data !== 'object') return data || {};\n\n\t\t\t// 幂等保护：已有 location 子对象This means是旧格式或 fallback 数据，None需二次处理\n\t\t\tif (data.location && typeof data.location === 'object') return data;\n\n\t\t\t// 复制原对象并保留扁平字段（cc/lat/lon/company_name/asn_num/asn_org 等仍可访问）\n\t\t\tconst normalized = Object.assign({}, data);\n\n\t\t\t// 构造 location 子对象（新版缺少 country/state/city/timezone，缺省enable it for undefined）\n\t\t\tnormalized.location = {\n\t\t\t\tcountry: data.country,\n\t\t\t\tcountry_code: data.cc,\n\t\t\t\tstate: data.state,\n\t\t\t\tcity: data.city,\n\t\t\t\tlatitude: data.lat,\n\t\t\t\tlongitude: data.lon,\n\t\t\t\ttimezone: data.timezone\n\t\t\t};\n\n\t\t\t// 构造 company 子对象（新版仅有 company_name，None type/abuser_score，缺省enable it for undefined）\n\t\t\tnormalized.company = {\n\t\t\t\tname: data.company_name,\n\t\t\t\ttype: data.company_type,\n\t\t\t\tabuser_score: data.company_abuser_score\n\t\t\t};\n\n\t\t\t// 构造 asn 子对象（新版仅有 asn_num/asn_org，None type/abuser_score，缺省enable it for undefined）\n\t\t\tnormalized.asn = {\n\t\t\t\tasn: data.asn_num,\n\t\t\t\torg: data.asn_org,\n\t\t\t\ttype: data.asn_type,\n\t\t\t\tabuser_score: data.asn_abuser_score\n\t\t\t};\n\n\t\t\treturn normalized;\n\t\t}\n\n\t\t// 显示 IP Details弹窗\n\t\tfunction showIpDetailModal(data) {\n\t\t\t// 首先移除旧的弹窗（如果存In）\n\t\t\tconst existingModal = document.querySelector('.ip-detail-modal');\n\t\t\tif (existingModal) existingModal.remove();\n\n\t\t\t// 创建弹窗\n\t\t\tconst modal = document.createElement('div');\n\t\t\tmodal.className = 'ip-detail-modal';\n\n\t\t\t// 计算评m和等级\n\t\t\tconst companyScore = data.company?.abuser_score;\n\t\t\tconst asnScore = data.asn?.abuser_score;\n\t\t\tconst securityFlags = {\n\t\t\t\tis_crawler: data.is_crawler,\n\t\t\t\tis_proxy: data.is_proxy,\n\t\t\t\tis_vpn: data.is_vpn,\n\t\t\t\tis_tor: data.is_tor,\n\t\t\t\tis_abuser: data.is_abuser,\n\t\t\t\tis_bogon: data.is_bogon\n\t\t\t};\n\n\t\t\tconst combinedScore = calculateAbuseScore(companyScore, asnScore, securityFlags);\n\t\t\tlet riskControlHTML = 'Unknown';\n\t\t\tlet riskLevel = 'Unknown';\n\t\t\tlet badgeClass = 'badge-info';\n\n\t\t\tif (combinedScore !== null) {\n\t\t\t\tconst scorePercentage = combinedScore * 100;\n\t\t\t\tbadgeClass = getAbuseScoreBadgeClass(scorePercentage);\n\t\t\t\tconst formattedScore = formatAbuseScorePercentage(combinedScore);\n\n\t\t\t\tif (scorePercentage >= 100) riskLevel = 'Critical risk';\n\t\t\t\telse if (scorePercentage >= 20) riskLevel = 'High risk';\n\t\t\t\telse if (scorePercentage >= 5) riskLevel = 'Low risk';\n\t\t\t\telse if (scorePercentage >= 0.25) riskLevel = 'Clean';\n\t\t\t\telse riskLevel = '极度Clean';\n\n\t\t\t\triskControlHTML = `<span class=\"ip-detail-badge ${badgeClass}\">${formattedScore} ${riskLevel}</span>`;\n\t\t\t}\n\n\t\t\t// 构建 HTML 结构\n\t\t\tmodal.innerHTML = `\n\t\t\t\t<div class=\"ip-detail-content\">\n\t\t\t\t\t<div class=\"ip-detail-header\">\n\t\t\t\t\t\t<h2 class=\"ip-detail-title\">\n\t\t\t\t\t\t\t🔍 IP Details\n\t\t\t\t\t\t\t<span class=\"ip-detail-source-tag\">Data source: ipapi.is</span>\n\t\t\t\t\t\t</h2>\n\t\t\t\t\t\t<button class=\"ip-detail-close\" title=\"Off\">&times;</button>\n\t\t\t\t\t</div>\n\t\t\t\t\t<div class=\"ip-detail-body\">\n\t\t\t\t\t\t<!-- 地图展示区 -->\n\t\t\t\t\t\t<div class=\"ip-detail-map-container\">\n\t\t\t\t\t\t\t<div id=\"ip-detail-map\"></div>\n\t\t\t\t\t\t</div>\n\n\t\t\t\t\t\t<!-- 数据网格区 -->\n\t\t\t\t\t\t<div class=\"ip-detail-grid-container\">\n\t\t\t\t\t\t\t<!-- 左栏: Basic Information (整合地理、运营商信息) -->\n\t\t\t\t\t\t\t<div class=\"ip-detail-left-col\">\n\t\t\t\t\t\t\t\t<div class=\"ip-detail-card\" style=\"height: 100%;\">\n\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-section-title\">📍 Basic Information</div>\n\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-item\" title=\"The public IP address currently queried, used to uniquely identify a device on the internet\">\n\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-label\">IP Address</span>\n\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-value\">${data.ip || 'Unknown'}</span>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-item\" title=\"Approximate physical location inferred from IP allocation databases, including country/region, state/province, and city\">\n\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-label\">Location</span>\n\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-value\">${data.location?.country_code ? `[${data.location.country_code}]` : ''}${data.location?.country || ''} ${[data.location?.state, data.location?.city].filter(Boolean).join('/') || 'Unknown'}</span>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-item\" title=\"Standard time zone for the IP location, formatted as Continent/City, e.g. Asia/Shanghai\">\n\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-label\">Time zone</span>\n\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-value\">${data.location?.timezone || 'Unknown'}</span>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-item\" title=\"Network type: Residential, Datacenter/cloud server, or Business leased line. The left side is the ISP category; the right side is the ASN (autonomous system) category.\">\n\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-label\">ISP / ASN Type</span>\n\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-value\">${formatIpType(data.company?.type)} / ${formatIpType(data.asn?.type)}</span>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-item\" title=\"Overall abuse score based on ISP/ASN history and security risks. Lower scores indicate a cleaner IP; higher scores indicate a greater likelihood of abuse.\">\n\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-label\">Risk Rating</span>\n\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-value\">${riskControlHTML}</span>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t</div>\n\n\t\t\t\t\t\t\t<!-- 右栏: Security Checks -->\n\t\t\t\t\t\t\t<div class=\"ip-detail-right-col\">\n\t\t\t\t\t\t\t\t<!-- Security Checks内容保持不变 -->\n\t\t\t\t\t\t\t\t<div class=\"ip-detail-card\" style=\"height: 100%;\">\n\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-section-title\">🛡️ Security Checks</div>\n\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-security-grid\">\n\t\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-item\" title=\"Whether the IP belongs to a datacenter, cloud provider, or hosting service. Some sites restrict datacenter IPs.\">\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-label\">Data Center</span>\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-value\">${data.is_datacenter ? '<span class=\"warning-text\">🏢 是</span>' : '✅ 否'}</span>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-item\" title=\"Whether the IP is identified as a public proxy (such as HTTP/SOCKS). Some services restrict proxy access.\">\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-label\">Proxy server</span>\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-value\">${data.is_proxy ? '<span class=\"danger-text\">⚠️ 是</span>' : '✅ 否'}</span>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-item\" title=\"Whether the IP belongs to a known VPN provider. Some websites restrict VPN traffic.\">\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-label\">VPN connection</span>\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-value\">${data.is_vpn ? '<span class=\"danger-text\">⚠️ 是</span>' : '✅ 否'}</span>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-item\" title=\"Whether the IP is a Tor exit node. Tor provides strong anonymity, but many sites restrict or block Tor exits.\">\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-label\">Tor 网络</span>\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-value\">${data.is_tor ? '<span class=\"danger-text\">⚠️ 是</span>' : '✅ 否'}</span>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-item\" title=\"Whether the IP is identified as a crawler or bot. Some sites restrict or specially handle crawler traffic.\">\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-label\">Web crawler</span>\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-value\">${data.is_crawler ? '<span class=\"danger-text\">🤖 是</span>' : '✅ 否'}</span>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-item\" title=\"Whether the IP is from a mobile carrier (4G/5G). Mobile IPs are usually dynamically assigned and change frequently.\">\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-label\">Mobile network</span>\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-value\">${data.is_mobile ? '<span class=\"success-text\">📱 是</span>' : 'No'}</span>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-item\" title=\"Whether the IP is from a satellite internet provider such as Starlink or OneWeb. Satellite connections often have higher latency.\">\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-label\">Satellite network</span>\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-value\">${data.is_satellite ? '<span class=\"success-text\">🛰️ 是</span>' : 'No'}</span>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-item\" title=\"Whether the IP has known abuse reports, such as spam, DDoS attacks, or malicious scans. Such IPs may be blocked or restricted.\">\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-label\">Known abuse</span>\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-value\">${data.is_abuser ? '<span class=\"danger-text\">⚠️ 是</span>' : '✅ 否'}</span>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t<div class=\"ip-detail-item\" title=\"Whether the IP is a Bogon address (reserved, private, or unallocated). These addresses should not appear on the public internet.\">\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-label\">Bogon IP</span>\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"ip-detail-value\">${data.is_bogon ? '<span class=\"danger-text\">⚠️ 是</span>' : '✅ 否'}</span>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t`;\n\n\t\t\tdocument.body.appendChild(modal);\n\n\t\t\t// 初始化弹窗内的地图\n\t\t\tif (data.location?.latitude && data.location?.longitude) {\n\t\t\t\tconst lat = parseFloat(data.location.latitude);\n\t\t\t\tconst lng = parseFloat(data.location.longitude);\n\n\t\t\t\t// 给 DOM 渲染留出一点点时间\n\t\t\t\tsetTimeout(() => {\n\t\t\t\t\tconst detailMap = L.map('ip-detail-map', {\n\t\t\t\t\t\tzoomControl: false,\n\t\t\t\t\t\tattributionControl: true\n\t\t\t\t\t}).setView([lat + 5, lng], 4); // 向上偏移中心点，使标记In视野内偏下\n\n\t\t\t\t\tL.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {\n\t\t\t\t\t\tsubdomains: 'abc',\n\t\t\t\t\t\tattribution: '&copy; <a href=\"https://www.openstreetmap.org/copyright\">OpenStreetMap</a> contributors',\n\t\t\t\t\t\tminZoom: 1,\n\t\t\t\t\t\tmaxZoom: 18\n\t\t\t\t\t}).addTo(detailMap);\n\n\t\t\t\t\tconst popupHTML = `\n\t\t\t\t\t\t<div class=\"ip-detail-popup-content\">\n\t\t\t\t\t\t\t<div class=\"ip-detail-popup-city\">\n\t\t\t\t\t\t\t\t${data.location?.city || data.location?.country || 'Location'}\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<div class=\"ip-detail-popup-item\">\n\t\t\t\t\t\t\t\t<span class=\"ip-detail-popup-label\">Country:</span>\n\t\t\t\t\t\t\t\t<span class=\"ip-detail-popup-value\">[${data.location?.country_code || '-'}]${data.location?.country || 'Unknown'}</span>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<div class=\"ip-detail-popup-item\">\n\t\t\t\t\t\t\t\t<span class=\"ip-detail-popup-label\">Exit IP:</span>\n\t\t\t\t\t\t\t\t<span class=\"ip-detail-popup-value\">${data.ip}</span>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<div class=\"ip-detail-popup-item\">\n\t\t\t\t\t\t\t\t<span class=\"ip-detail-popup-label\">ASN:</span>\n\t\t\t\t\t\t\t\t<span class=\"ip-detail-popup-value\">${data.asn?.asn || ''}</span>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<div class=\"ip-detail-popup-item\">\n\t\t\t\t\t\t\t\t<span class=\"ip-detail-popup-label\">Carrier:</span>\n\t\t\t\t\t\t\t\t<span class=\"ip-detail-popup-value\">${data.company?.name || 'Unknown'}</span>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t`;\n\n\t\t\t\t\tL.marker([lat, lng])\n\t\t\t\t\t\t.addTo(detailMap)\n\t\t\t\t\t\t.bindPopup(popupHTML, { closeButton: false, offset: [0, -32] })\n\t\t\t\t\t\t.openPopup();\n\n\t\t\t\t\t// 偶尔地图布局会出问题，强制刷新\n\t\t\t\t\tdetailMap.invalidateSize();\n\t\t\t\t}, 400);\n\t\t\t} else {\n\t\t\t\t// 如果没有经纬度，隐藏地图容器\n\t\t\t\tconst mapContainer = modal.querySelector('.ip-detail-map-container');\n\t\t\t\tif (mapContainer) mapContainer.style.display = 'none';\n\t\t\t}\n\n\t\t\t// Off逻辑\n\t\t\tconst closeBtn = modal.querySelector('.ip-detail-close');\n\t\t\tconst closeFunc = () => {\n\t\t\t\tmodal.style.opacity = '0';\n\t\t\t\tmodal.querySelector('.ip-detail-content').style.transform = 'translateY(20px)';\n\t\t\t\tsetTimeout(() => modal.remove(), 300);\n\t\t\t};\n\n\t\t\tcloseBtn.onclick = closeFunc;\n\t\t\tmodal.onclick = (e) => { if (e.target === modal) closeFunc(); };\n\n\t\t\t// ESC 键Off\n\t\t\tconst escHandler = (e) => {\n\t\t\t\tif (e.key === 'Escape') {\n\t\t\t\t\tcloseFunc();\n\t\t\t\t\tdocument.removeEventListener('keydown', escHandler);\n\t\t\t\t}\n\t\t\t};\n\t\t\tdocument.addEventListener('keydown', escHandler);\n\t\t}\n\n\t\t// ==================== 获取更多 PROXYIP 相关函数 ====================\n\n\t\tfunction showGetMoreProxyIPModal() {\n\t\t\tshowExploreProxyModal('proxyip');\n\t\t\t// Reset已选\n\t\t\tselectedProxyIPs = [];\n\t\t\tupdateSelectedProxyIPsUI();\n\t\t}\n\n\t\tfunction closeGetMoreProxyIPModal(event) {\n\t\t\tcloseExploreProxyModal('proxyip', event);\n\t\t}\n\n\t\tfunction onProxyIPDataRegionChange() {\n\t\t\tonProxyRegionChange('proxyip');\n\t\t}\n\n\t\tasync function verifySingleProxyIP(proxy, signal) {\n\t\t\tconst config = proxyConfigs['proxyip'];\n\t\t\tconst proxyIp = proxy.proxy; // format: ip\n\n\t\t\tif (signal && signal.aborted) return;\n\n\t\t\t// 设置15s超时\n\t\t\tconst timeoutId = setTimeout(() => {\n\t\t\t\twindow[config.verificationStatus][proxyIp] = {\n\t\t\t\t\tstatus: 'timeout',\n\t\t\t\t\tresponseTime: null\n\t\t\t\t};\n\t\t\t\tupdateProxyDisplay('proxyip');\n\t\t\t}, 10000);\n\n\t\t\twindow[config.verificationTimeouts][proxyIp] = timeoutId;\n\n\t\t\ttry {\n\t\t\t\tconst response = await fetch(`https://api.090227.xyz/check?proxyip=${proxyIp}`, { signal });\n\t\t\t\tclearTimeout(window[config.verificationTimeouts][proxyIp]);\n\n\t\t\t\tif (response.ok) {\n\t\t\t\t\tconst data = await response.json();\n\t\t\t\t\tif (data.success) {\n\t\t\t\t\t\twindow[config.verificationStatus][proxyIp] = {\n\t\t\t\t\t\t\tstatus: 'success',\n\t\t\t\t\t\t\tresponseTime: data.responseTime,\n\t\t\t\t\t\t\tsupports_ipv4: data.supports_ipv4 === true,\n\t\t\t\t\t\t\tsupports_ipv6: data.supports_ipv6 === true\n\t\t\t\t\t\t};\n\t\t\t\t\t} else {\n\t\t\t\t\t\twindow[config.verificationStatus][proxyIp] = {\n\t\t\t\t\t\t\tstatus: 'failed',\n\t\t\t\t\t\t\tresponseTime: null\n\t\t\t\t\t\t};\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\twindow[config.verificationStatus][proxyIp] = {\n\t\t\t\t\t\tstatus: 'failed',\n\t\t\t\t\t\tresponseTime: null\n\t\t\t\t\t};\n\t\t\t\t}\n\t\t\t} catch (error) {\n\t\t\t\tif (signal && signal.aborted) return;\n\t\t\t\twindow[config.verificationStatus][proxyIp] = {\n\t\t\t\t\tstatus: 'failed',\n\t\t\t\t\tresponseTime: null\n\t\t\t\t};\n\t\t\t}\n\t\t\tupdateProxyDisplay('proxyip');\n\t\t}\n\n\t\tfunction addSelectedProxyIP() {\n\t\t\tconst select = document.getElementById('proxyIPProxySelect');\n\t\t\tconst ip = select.value;\n\t\t\tif (!ip) return;\n\n\t\t\tif (selectedProxyIPs.length >= 8) {\n\t\t\t\tshowToast('You can select up to 8 ProxyIPs', 'warning');\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\tif (selectedProxyIPs.includes(ip)) {\n\t\t\t\tshowToast('This IP is already selected', 'warning');\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\tselectedProxyIPs.push(ip);\n\t\t\tupdateSelectedProxyIPsUI();\n\t\t\tupdateProxyIPConfirmButton();\n\t\t}\n\n\t\tfunction removeSelectedProxyIP(ip) {\n\t\t\tselectedProxyIPs = selectedProxyIPs.filter(item => item !== ip);\n\t\t\tupdateSelectedProxyIPsUI();\n\t\t\tupdateProxyIPConfirmButton();\n\t\t}\n\n\t\tfunction updateSelectedProxyIPsUI() {\n\t\t\tconst container = document.getElementById('selectedProxyIPsContainer');\n\t\t\tcontainer.innerHTML = '';\n\n\t\t\tselectedProxyIPs.forEach(ip => {\n\t\t\t\t// 查找对应的国家 emoji\n\t\t\t\tconst dataList = window.proxyIPListData || [];\n\t\t\t\tconst proxyData = dataList.find(p => p.ip === ip);\n\t\t\t\tconst emoji = proxyData?.country_emoji || '🌐';\n\n\t\t\t\t// 构建 title 信息\n\t\t\t\tlet titleText = '';\n\t\t\t\tif (proxyData) {\n\t\t\t\t\tconst country = proxyData.country || 'Unknown';\n\t\t\t\t\tconst countryName = englishProxyLabel(proxyData.country_en, country);\n\t\t\t\t\tconst city = englishProxyLabel(proxyData.city, countryName);\n\t\t\t\t\tconst clientIp = proxyData.clientIp || ip;\n\t\t\t\t\tconst asn = proxyData.asn || 'Unknown';\n\t\t\t\t\tconst asOrganization = proxyData.asOrganization || 'Unknown';\n\n\t\t\t\t\ttitleText = `${city}\\nCountry: [${country}]${countryName}\\nExit IP: ${clientIp}\\nASN: ${asn}\\nCarrier: ${asOrganization}`;\n\t\t\t\t}\n\n\t\t\t\tconst tag = document.createElement('div');\n\t\t\t\ttag.style.cssText = 'background: #fee2e2; border: 1px solid #ef4444; color: #b91c1c; padding: 4px 10px; border-radius: 9999px; display: flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 500;';\n\t\t\t\tif (titleText) {\n\t\t\t\t\ttag.title = titleText;\n\t\t\t\t}\n\t\t\t\ttag.innerHTML = `\n\t\t\t\t\t<span>${emoji} ${ip}</span>\n\t\t\t\t\t<span onclick=\"removeSelectedProxyIP('${ip}')\" style=\"cursor: pointer; font-weight: bold; font-size: 16px;\">×</span>\n\t\t\t\t`;\n\t\t\t\tcontainer.appendChild(tag);\n\t\t\t});\n\t\t}\n\n\t\tfunction updateProxyIPConfirmButton() {\n\t\t\tconst btn = document.getElementById('proxyIPConfirmBtn');\n\t\t\tbtn.disabled = selectedProxyIPs.length === 0;\n\t\t}\n\n\t\tfunction confirmSelectProxyIP() {\n\t\t\tconst input = document.getElementById('proxyIP');\n\t\t\tif (input) {\n\t\t\t\tinput.value = selectedProxyIPs.join(',');\n\t\t\t\tinput.dispatchEvent(new Event('change', { bubbles: true }));\n\t\t\t\tmarkModified('proxy');\n\t\t\t}\n\n\t\t\tcloseGetMoreProxyIPModal();\n\n\t\t\t// 如果勾选了自动获取，Cancel勾选\n\t\t\tconst autoProxyCheck = document.getElementById('autoProxy');\n\t\t\tif (autoProxyCheck && autoProxyCheck.checked) {\n\t\t\t\tautoProxyCheck.checked = false;\n\t\t\t\tif (typeof toggleAutoProxy === 'function') toggleAutoProxy();\n\t\t\t}\n\n\t\t\tconst config = proxyConfigs['proxyip'];\n\t\t\tif (config.abortController) {\n\t\t\t\tconfig.abortController.abort();\n\t\t\t\tconfig.abortController = null;\n\t\t\t}\n\n\t\t\t// 亮起Save和Cancel按钮\n\t\t\tconst saveBtn = document.getElementById('saveProxyBtn');\n\t\t\tconst cancelBtn = document.getElementById('cancelProxyBtn');\n\t\t\tif (saveBtn) saveBtn.disabled = false;\n\t\t\tif (cancelBtn) cancelBtn.disabled = false;\n\t\t}\n\n\t\t// ==================== SOCKS5 相关函数 ====================\n\n\t\t// 代理类型配置\n\t\tconst proxyConfigs = {\n\t\t\tsocks5: {\n\t\t\t\tmodalId: 'exploreSocks5Modal',\n\t\t\t\tregionSelectId: 'socks5RegionSelect',\n\t\t\t\tproxySelectId: 'socks5ProxySelect',\n\t\t\t\tproxySelectGroupId: 'socks5ProxySelectGroup',\n\t\t\t\tconfirmBtnId: 'socks5ConfirmBtn',\n\t\t\t\tlistData: 'socks5ListData',\n\t\t\t\tcountryMap: 'socks5CountryMap',\n\t\t\t\tverificationStatus: 'socks5VerificationStatus',\n\t\t\t\tverificationTimeouts: 'socks5VerificationTimeouts',\n\t\t\t\turl: 'https://raw.githubusercontent.com/EDT-Pages/Proxy-List/main/data/socks5.json',\n\t\t\t\tdescription: 'SOCKS5列表',\n\t\t\t\tinputId: 'socks5Addr',\n\t\t\t\tabortController: null,\n\t\t\t\tverifySingleFunction: (proxy, signal) => verifySingleProxy(proxy, 'socks5', signal)\n\t\t\t},\n\t\t\thttp: {\n\t\t\t\tmodalId: 'exploreHTTPModal',\n\t\t\t\tregionSelectId: 'httpRegionSelect',\n\t\t\t\tproxySelectId: 'httpProxySelect',\n\t\t\t\tproxySelectGroupId: 'httpProxySelectGroup',\n\t\t\t\tconfirmBtnId: 'httpConfirmBtn',\n\t\t\t\tlistData: 'httpListData',\n\t\t\t\tcountryMap: 'httpCountryMap',\n\t\t\t\tverificationStatus: 'httpVerificationStatus',\n\t\t\t\tverificationTimeouts: 'httpVerificationTimeouts',\n\t\t\t\turl: 'https://raw.githubusercontent.com/EDT-Pages/Proxy-List/main/data/http.json',\n\t\t\t\tdescription: 'HTTP列表',\n\t\t\t\tinputId: 'httpAddr',\n\t\t\t\tabortController: null,\n\t\t\t\tverifySingleFunction: (proxy, signal) => verifySingleProxy(proxy, 'http', signal)\n\t\t\t},\n\t\t\thttps: {\n\t\t\t\tmodalId: 'exploreHTTPSModal',\n\t\t\t\tregionSelectId: 'httpsRegionSelect',\n\t\t\t\tproxySelectId: 'httpsProxySelect',\n\t\t\t\tproxySelectGroupId: 'httpsProxySelectGroup',\n\t\t\t\tconfirmBtnId: 'httpsConfirmBtn',\n\t\t\t\tlistData: 'httpsListData',\n\t\t\t\tcountryMap: 'httpsCountryMap',\n\t\t\t\tverificationStatus: 'httpsVerificationStatus',\n\t\t\t\tverificationTimeouts: 'httpsVerificationTimeouts',\n\t\t\t\turl: 'https://raw.githubusercontent.com/EDT-Pages/Proxy-List/main/data/https.json',\n\t\t\t\tdescription: 'HTTPS列表',\n\t\t\t\tinputId: 'httpsAddr',\n\t\t\t\tabortController: null,\n\t\t\t\tverifySingleFunction: (proxy, signal) => verifySingleProxy(proxy, 'https', signal)\n\t\t\t},\n\t\t\tproxyip: {\n\t\t\t\tmodalId: 'getMoreProxyIPModal',\n\t\t\t\tregionSelectId: 'proxyIPDataRegionSelect',\n\t\t\t\tproxySelectId: 'proxyIPProxySelect',\n\t\t\t\tproxySelectGroupId: 'proxyIPProxySelectGroup',\n\t\t\t\tconfirmBtnId: 'proxyIPConfirmBtn',\n\t\t\t\tlistData: 'proxyIPListData',\n\t\t\t\tcountryMap: 'proxyIPCountryMap',\n\t\t\t\tverificationStatus: 'proxyIPVerificationStatus',\n\t\t\t\tverificationTimeouts: 'proxyIPVerificationTimeouts',\n\t\t\t\turl: 'https://zip.cm.edu.kg.cmliussss.net/all.json',\n\t\t\t\tdescription: 'ProxyIP列表',\n\t\t\t\tinputId: 'proxyIP',\n\t\t\t\tabortController: null,\n\t\t\t\tverifySingleFunction: (proxy, signal) => verifySingleProxyIP(proxy, signal)\n\t\t\t}\n\t\t};\n\n\t\t// 存储SOCKS5数据\n\t\tlet socks5ListData = [];\n\t\tlet socks5CountryMap = {};\n\t\tlet socks5VerificationStatus = {}; // 存储验证状态\n\t\tlet socks5VerificationTimeouts = {}; // 存储超时计时器\n\n\t\t// 存储 ProxyIP 数据\n\t\tlet proxyIPListData = [];\n\t\tlet proxyIPCountryMap = {};\n\t\tlet proxyIPVerificationStatus = {};\n\t\tlet proxyIPVerificationTimeouts = {};\n\t\tlet selectedProxyIPs = []; // 存储用户选择的 ProxyIP\n\n\t\tfunction showExploreSocks5Modal() {\n\t\t\tshowExploreProxyModal('socks5');\n\t\t}\n\n\t\tfunction closeExploreSocks5Modal(event) {\n\t\t\tcloseExploreProxyModal('socks5', event);\n\t\t}\n\n\t\tfunction loadSocks5List() {\n\t\t\tloadProxyList('socks5');\n\t\t}\n\n\t\tfunction buildCountryMap(listData, countryMap) {\n\t\t\tcountryMap = {};\n\n\t\t\t// 统计每个国家的代理数量\n\t\t\tlistData.forEach(item => {\n\t\t\t\tconst country = item.country;\n\t\t\t\tif (!countryMap[country]) {\n\t\t\t\t\tcountryMap[country] = [];\n\t\t\t\t}\n\t\t\t\tcountryMap[country].push(item);\n\t\t\t});\n\n\t\t\t// 按数量排序（多到少）\n\t\t\tcountryMap = Object.fromEntries(\n\t\t\t\tObject.entries(countryMap).sort((a, b) => b[1].length - a[1].length)\n\t\t\t);\n\n\t\t\treturn countryMap;\n\t\t}\n\n\t\tfunction populateSocks5RegionSelect() {\n\t\t\tpopulateProxyRegionSelect('socks5');\n\t\t}\n\n\t\tfunction onSocks5RegionChange() {\n\t\t\tonProxyRegionChange('socks5');\n\t\t}\n\n\t\tfunction populateSocks5ProxySelect(selectedCountry) {\n\t\t\tpopulateProxySelect(selectedCountry, 'socks5ProxySelect', socks5CountryMap, socks5VerificationStatus, 'socks5');\n\t\t}\n\n\t\tfunction verifySocks5Proxies(proxies) {\n\t\t\tverifyProxies(proxies, verifySingleSocks5);\n\t\t}\n\n\t\tfunction verifySingleSocks5(proxy, signal) {\n\t\t\treturn verifySingleProxy(proxy, 'socks5', signal);\n\t\t}\n\n\t\tfunction updateSocks5Display() {\n\t\t\tupdateProxyDisplay('socks5');\n\t\t}\n\n\t\tfunction confirmSelectSocks5() {\n\t\t\tconfirmSelectProxy('socks5');\n\t\t}\n\n\t\tfunction updateSocks5ConfirmButton() {\n\t\t\tupdateProxyConfirmButton('socks5');\n\t\t}\n\n\t\t// 通用代理选择器填充函数\n\t\tfunction populateProxySelect(selectedCountry, selectId, countryMap, verificationStatus, type) {\n\t\t\tconst select = document.getElementById(selectId);\n\t\t\tconst proxies = countryMap[selectedCountry] || [];\n\n\t\t\t// Save当前选中的值\n\t\t\tconst currentValue = select.value;\n\n\t\t\t// 检查是否所有代理都验证完成\n\t\t\tconst allVerified = proxies.every(p => {\n\t\t\t\tconst status = verificationStatus[p.proxy];\n\t\t\t\treturn status && status.status !== 'pending';\n\t\t\t});\n\n\t\t\t// 获取当前Region的所有代理，并按状态和延迟排序\n\t\t\tconst sortedProxies = [...proxies].sort((a, b) => {\n\t\t\t\tconst statusA = verificationStatus[a.proxy] || { status: 'pending' };\n\t\t\t\tconst statusB = verificationStatus[b.proxy] || { status: 'pending' };\n\n\t\t\t\t// 可用的In前面，且按延迟从低到高\n\t\t\t\tif (statusA.status === 'success' && statusB.status === 'success') {\n\t\t\t\t\treturn (statusA.responseTime || 0) - (statusB.responseTime || 0);\n\t\t\t\t}\n\t\t\t\tif (statusA.status === 'success') return -1;\n\t\t\t\tif (statusB.status === 'success') return 1;\n\n\t\t\t\treturn 0;\n\t\t\t});\n\n\t\t\t// 检查是否有成功的代理\n\t\t\tconst successfulProxies = sortedProxies.filter(proxy => verificationStatus[proxy.proxy]?.status === 'success');\n\n\t\t\t// 辅助函数：生成代理选项HTML\n\t\t\tfunction generateProxyOption(proxy, isSelectable = false) {\n\t\t\t\tconst status = verificationStatus[proxy.proxy] || { status: 'pending' };\n\t\t\t\tlet emoji = '⏳';\n\t\t\t\tlet statusText = 'Verifying';\n\n\t\t\t\tif (status.status === 'success') {\n\t\t\t\t\tif (type === 'proxyip') {\n\t\t\t\t\t\tconst supportsV4 = status.supports_ipv4 === true;\n\t\t\t\t\t\tconst supportsV6 = status.supports_ipv6 === true;\n\n\t\t\t\t\t\tif (supportsV4 && supportsV6) {\n\t\t\t\t\t\t\temoji = '✅✅';\n\t\t\t\t\t\t} else if (supportsV4 && !supportsV6) {\n\t\t\t\t\t\t\temoji = '✅🔴';\n\t\t\t\t\t\t} else if (!supportsV4 && supportsV6) {\n\t\t\t\t\t\t\temoji = '🔴✅';\n\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\temoji = '🔴🔴';\n\t\t\t\t\t\t}\n\t\t\t\t\t} else {\n\t\t\t\t\t\temoji = '✅';\n\t\t\t\t\t}\n\t\t\t\t\tstatusText = `${status.responseTime}ms`;\n\t\t\t\t} else if (status.status === 'timeout') {\n\t\t\t\t\temoji = '🔴';\n\t\t\t\t\tstatusText = 'Timed out';\n\t\t\t\t} else if (status.status === 'failed') {\n\t\t\t\t\temoji = '🔴';\n\t\t\t\t\tstatusText = 'Unavailable';\n\t\t\t\t}\n\n\t\t\t\t// ProxyIP 模式下 label 稍微不同，不包含协议前缀\n\t\t\t\tconst label = type === 'proxyip'\n\t\t\t\t\t? `${emoji}[${statusText}]${proxy.ip}${proxy.city ? ` - ${proxy.city}` : ''},AS${proxy.asn}`\n\t\t\t\t\t: `${emoji}[${statusText}]${proxy.city},AS${proxy.asn},${proxy.asOrganization}`;\n\n\t\t\t\tconst disabled = !isSelectable || status.status !== 'success';\n\t\t\t\t// ProxyIP 不需要默认选中，因enable it for是多选触发\n\t\t\t\tconst selected = type !== 'proxyip' && isSelectable && status.status === 'success' && successfulProxies.indexOf(proxy) === 0 ? 'selected' : '';\n\t\t\t\treturn `<option value=\"${proxy.proxy}\" ${disabled ? 'disabled' : ''} ${selected}>${label}</option>`;\n\t\t\t}\n\n\t\t\tlet html = type === 'proxyip' ? '<option value=\"\">-- Select a proxy --</option>' : '';\n\t\t\tif (successfulProxies.length > 0) {\n\t\t\t\t// 有成功的代理，显示所有代理\n\t\t\t\tsortedProxies.forEach(proxy => {\n\t\t\t\t\thtml += generateProxyOption(proxy, true);\n\t\t\t\t});\n\t\t\t} else if (allVerified) {\n\t\t\t\t// 验证完成但没有成功的代理\n\t\t\t\thtml = '<option value=\"\">No proxies are available in this region. Please choose another region.</option>';\n\t\t\t} else {\n\t\t\t\t// Verifying，显示代理列表\n\t\t\t\thtml = (type === 'proxyip' ? '<option value=\"\">Checking availability, please wait...</option>' : '<option value=\"\">Checking availability, please wait...</option>');\n\t\t\t\tsortedProxies.forEach(proxy => {\n\t\t\t\t\thtml += generateProxyOption(proxy, false);\n\t\t\t\t});\n\t\t\t}\n\n\t\t\tselect.innerHTML = html;\n\n\t\t\t// 恢复用户的选择 (ProxyIP 模式下如果当前选中的仍然有效，也恢复)\n\t\t\tif (successfulProxies.length > 0) {\n\t\t\t\tif (currentValue && successfulProxies.some(p => p.proxy === currentValue)) {\n\t\t\t\t\tselect.value = currentValue;\n\t\t\t\t} else if (type !== 'proxyip') {\n\t\t\t\t\tselect.value = successfulProxies[0].proxy;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\t// 通用代理验证函数\n\t\t// Fisher-Yates 打乱算法 - 随机打乱数组顺序\n\t\tfunction shuffleArray(array) {\n\t\t\tconst shuffled = [...array]; // 创建副本，不修改原数组\n\t\t\tfor (let i = shuffled.length - 1; i > 0; i--) {\n\t\t\t\tconst j = Math.floor(Math.random() * (i + 1));\n\t\t\t\t// 交换元素\n\t\t\t\t[shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];\n\t\t\t}\n\t\t\treturn shuffled;\n\t\t}\n\n\t\tfunction verifyProxies(proxies, verifySingleFunction, onProgress, signal) {\n\t\t\t// 打乱代理列表的顺序，避免多个用户同时测试时都从头开始\n\t\t\tconst shuffledProxies = shuffleArray(proxies);\n\n\t\t\t// 并发控制：最多8个并发请求\n\t\t\tconst maxConcurrent = 8;\n\t\t\tlet currentIndex = 0;\n\t\t\tlet activeRequests = 0;\n\n\t\t\tfunction startNextProxy() {\n\t\t\t\tif (signal && signal.aborted) return;\n\t\t\t\tif (currentIndex >= shuffledProxies.length || activeRequests >= maxConcurrent) {\n\t\t\t\t\treturn;\n\t\t\t\t}\n\n\t\t\t\tactiveRequests++;\n\t\t\t\tconst proxy = shuffledProxies[currentIndex++];\n\n\t\t\t\tverifySingleFunction(proxy, signal).finally(() => {\n\t\t\t\t\tactiveRequests--;\n\t\t\t\t\tif (onProgress) onProgress();\n\t\t\t\t\tstartNextProxy();\n\t\t\t\t});\n\t\t\t}\n\n\t\t\t// 启动初始8个请求\n\t\t\tfor (let i = 0; i < Math.min(maxConcurrent, shuffledProxies.length); i++) {\n\t\t\t\tstartNextProxy();\n\t\t\t}\n\t\t}\n\n\t\t// 通用代理探索函数\n\t\tfunction showExploreProxyModal(type) {\n\t\t\tconst config = proxyConfigs[type];\n\t\t\tconst modal = document.getElementById(config.modalId);\n\t\t\tif (!modal) return;\n\n\t\t\t// Reset状态\n\t\t\twindow[config.listData] = [];\n\t\t\twindow[config.countryMap] = {};\n\t\t\twindow[config.verificationStatus] = {};\n\t\t\twindow[config.verificationTimeouts] = {};\n\t\t\tlastMappedProxy[type] = null;\n\n\t\t\tmodal.classList.add('show');\n\t\t\tdocument.getElementById(config.regionSelectId).innerHTML = '<option value=\"\">Loading...</option>';\n\t\t\tdocument.getElementById(config.proxySelectGroupId).style.display = 'block';\n\t\t\tdocument.getElementById(config.confirmBtnId).disabled = true;\n\n\t\t\t// 初始化下拉框 focus/blur 监听（首次生效）\n\t\t\tensureProxySelectListeners(type);\n\t\t\t// Reset节流状态\n\t\t\tresetProxyDisplayUpdateState(type);\n\n\t\t\t// 加载列表\n\t\t\tloadProxyList(type);\n\n\t\t\t// 初始化或更新地图容器\n\t\t\tsetTimeout(() => {\n\t\t\t\tinitProxyMap(type);\n\t\t\t}, 300);\n\t\t}\n\n\t\tconst lastMappedProxy = {\n\t\t\tsocks5: null,\n\t\t\thttp: null,\n\t\t\thttps: null,\n\t\t\tproxyip: null\n\t\t};\n\n\t\tconst proxyMaps = {\n\t\t\tsocks5: { map: null, marker: null },\n\t\t\thttp: { map: null, marker: null },\n\t\t\thttps: { map: null, marker: null },\n\t\t\tproxyip: { map: null, marker: null }\n\t\t};\n\n\t\tfunction initProxyMap(type) {\n\t\t\tconst containerId = type === 'socks5' ? 'proxy-map-socks5' : (type === 'http' ? 'proxy-map-http' : (type === 'https' ? 'proxy-map-https' : 'proxy-map-proxyip'));\n\t\t\tconst container = document.getElementById(containerId);\n\t\t\tif (!container) return;\n\n\t\t\t// 如果地图已存In，先刷新布局\n\t\t\tif (proxyMaps[type] && proxyMaps[type].map) {\n\t\t\t\tproxyMaps[type].map.invalidateSize();\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\tif (!proxyMaps[type]) proxyMaps[type] = { map: null, marker: null };\n\n\t\t\t// 创建地图\n\t\t\tconst map = L.map(containerId, {\n\t\t\t\tzoomControl: false, // Keep the map controls compact.\n\t\t\t\tattributionControl: true\n\t\t\t}).setView([22.2783, 114.1747], 4);\n\n\t\t\tL.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {\n\t\t\t\tsubdomains: 'abc',\n\t\t\t\tattribution: '&copy; <a href=\"https://www.openstreetmap.org/copyright\">OpenStreetMap</a> contributors',\n\t\t\t\tminZoom: 1,\n\t\t\t\tmaxZoom: 18\n\t\t\t}).addTo(map);\n\n\t\t\tproxyMaps[type].map = map;\n\t\t}\n\n\t\tfunction updateProxyMap(type) {\n\t\t\tconst config = proxyConfigs[type];\n\t\t\tconst select = document.getElementById(config.proxySelectId);\n\t\t\tconst selectedProxyUrl = select.value;\n\t\t\tif (!selectedProxyUrl || !proxyMaps[type].map) return;\n\n\t\t\t// 如果该代理已经显示In地图上了，就不再重复加载，避免频繁刷新导致的气泡闪烁\n\t\t\tif (lastMappedProxy[type] === selectedProxyUrl) return;\n\t\t\tlastMappedProxy[type] = selectedProxyUrl;\n\n\t\t\t// 从数据列表中找到完整的代理信息\n\t\t\tconst proxyData = window[config.listData].find(p => p.proxy === selectedProxyUrl);\n\t\t\tif (!proxyData || proxyData.latitude === null || proxyData.longitude === null) return;\n\n\t\t\tconst lat = parseFloat(proxyData.latitude);\n\t\t\tconst lng = parseFloat(proxyData.longitude);\n\t\t\tconst map = proxyMaps[type].map;\n\n\t\t\t// 更新或创建 Marker\n\t\t\tif (proxyMaps[type].marker) {\n\t\t\t\tproxyMaps[type].marker.setLatLng([lat, lng]);\n\t\t\t} else {\n\t\t\t\tproxyMaps[type].marker = L.marker([lat, lng]).addTo(map);\n\t\t\t}\n\n\t\t\t// 平滑移动地图 - 将标记点定位到地图的下方60%位置，避免气泡被遮挡\n\t\t\tmap.setZoom(4);\n\n\t\t\t// 计算偏移后的中心点，使标记显示In视图的60%处（下方）\n\t\t\tconst mapSize = map.getSize();\n\t\t\tconst offsetY = mapSize.y * 0.2; // 向上偏移20%，使标记显示In60%处\n\t\t\tconst point = map.project([lat, lng], 4).subtract([0, offsetY]);\n\t\t\tconst offsetCenter = map.unproject(point, 4);\n\n\t\t\tif (isLowPerformanceMode) {\n\t\t\t\tmap.setView(offsetCenter, 4, { animate: false });\n\t\t\t} else {\n\t\t\t\tmap.flyTo(offsetCenter, 4, {\n\t\t\t\t\tduration: 1.5\n\t\t\t\t});\n\t\t\t}\n\n\t\t\t// 添加或更新 Popup\n\t\t\tconst isDark = document.documentElement.classList.contains('dark-mode');\n\t\t\tconst textColor = isDark ? '#ffffff' : '#333333';\n\t\t\tconst popupContent = `\n\t\t\t\t<div class=\"ip-detail-popup-city\">\n\t\t\t\t\t${englishProxyLabel(proxyData.city, proxyData.country_en || proxyData.country || 'Location')}\n\t\t\t\t</div>\n\t\t\t\t<div class=\"ip-detail-popup-item\">\n\t\t\t\t\t<span class=\"ip-detail-popup-label\">Country:</span>\n\t\t\t\t\t<span class=\"ip-detail-popup-value\">[${proxyData.country || '-'}] ${englishProxyLabel(proxyData.country_en, proxyData.country || '')}</span>\n\t\t\t\t</div>\n\t\t\t\t<div class=\"ip-detail-popup-item\">\n\t\t\t\t\t<span class=\"ip-detail-popup-label\">Exit IP:</span>\n\t\t\t\t\t<span class=\"ip-detail-popup-value\">${proxyData.clientIp || proxyData.ip || '-'}</span>\n\t\t\t\t</div>\n\t\t\t\t<div class=\"ip-detail-popup-item\">\n\t\t\t\t\t<span class=\"ip-detail-popup-label\">ASN:</span>\n\t\t\t\t\t<span class=\"ip-detail-popup-value\">${proxyData.asn || ''}</span>\n\t\t\t\t</div>\n\t\t\t\t<div class=\"ip-detail-popup-item\">\n\t\t\t\t\t<span class=\"ip-detail-popup-label\">Carrier:</span>\n\t\t\t\t\t<span class=\"ip-detail-popup-value\">${proxyData.asOrganization || 'Unknown'}</span>\n\t\t\t\t</div>\n\t\t\t`;\n\t\t\tproxyMaps[type].marker.bindPopup(popupContent, { offset: L.point(0, -32) }).openPopup();\n\t\t}\n\n\t\tfunction closeExploreProxyModal(type, event) {\n\t\t\tif (event && event.preventDefault) event.preventDefault();\n\t\t\tconst config = proxyConfigs[type];\n\t\t\tconst modal = document.getElementById(config.modalId);\n\t\t\tif (modal) {\n\t\t\t\tmodal.classList.remove('show');\n\t\t\t}\n\n\t\t\t// 停止正In进行的测试\n\t\t\tif (config.abortController) {\n\t\t\t\tconfig.abortController.abort();\n\t\t\t\tconfig.abortController = null;\n\t\t\t}\n\n\t\t\t// 清除所有超时计时器\n\t\t\tfor (let timeout of Object.values(window[config.verificationTimeouts])) {\n\t\t\t\tclearTimeout(timeout);\n\t\t\t}\n\n\t\t\t// 清理节流定时器\n\t\t\tresetProxyDisplayUpdateState(type);\n\t\t}\n\n\t\tfunction loadProxyList(type) {\n\t\t\tconst config = proxyConfigs[type];\n\t\t\tconst url = config.url;\n\n\t\t\tfetchWithAutoMirror(url, config.description)\n\t\t\t\t.then(text => {\n\t\t\t\t\tlet data = JSON.parse(text);\n\t\t\t\t\tif (type === 'proxyip') {\n\t\t\t\t\t\t// all.json format has a 'data' array\n\t\t\t\t\t\tdata = data.data.filter(item =>\n\t\t\t\t\t\t\tArray.isArray(item.port) ? item.port.includes(443) : item.port === 443\n\t\t\t\t\t\t).map(item => ({\n\t\t\t\t\t\t\tproxy: item.ip,\n\t\t\t\t\t\t\tip: item.ip,\n\t\t\t\t\t\t\tcountry: item.meta?.country || 'Unknown',\n\t\t\t\t\t\t\tcountry_cn: item.meta?.country_cn || 'Unknown',\n\t\t\t\t\t\t\tcountry_en: item.meta?.country_en || 'Unknown',\n\t\t\t\t\t\t\tcountry_emoji: item.meta?.country_emoji || '🏳️',\n\t\t\t\t\t\t\tcity: item.meta?.city || 'Unknown',\n\t\t\t\t\t\t\tclientIp: item.meta?.clientIp || item.ip,\n\t\t\t\t\t\t\tasn: item.meta?.asn || 0,\n\t\t\t\t\t\t\tasOrganization: item.meta?.asOrganization || 'Unknown',\n\t\t\t\t\t\t\tcontinent: item.meta?.continent || 'Unknown',\n\t\t\t\t\t\t\tlatitude: item.meta?.latitude !== undefined ? item.meta.latitude : (item.meta?.colo?.lat !== undefined ? item.meta.colo.lat : null),\n\t\t\t\t\t\t\tlongitude: item.meta?.longitude !== undefined ? item.meta.longitude : (item.meta?.colo?.lon !== undefined ? item.meta.colo.lon : null)\n\t\t\t\t\t\t}));\n\t\t\t\t\t}\n\t\t\t\t\twindow[config.listData] = data;\n\t\t\t\t\twindow[config.countryMap] = buildCountryMap(window[config.listData], window[config.countryMap]);\n\t\t\t\t\tpopulateProxyRegionSelect(type);\n\t\t\t\t})\n\t\t\t\t.catch(error => {\n\t\t\t\t\tconsole.error(`${config.description}Loading failed:`, error);\n\t\t\t\t\tdocument.getElementById(config.regionSelectId).innerHTML = '<option value=\"\">Loading failed</option>';\n\t\t\t\t});\n\t\t}\n\n\t\t// 大洲信息映射\n\t\tconst continentInfo = {\n\t\t\t'AS': { emoji: '🌏', name: 'Asia' },\n\t\t\t'NA': { emoji: '🌎', name: 'North America' },\n\t\t\t'EU': { emoji: '🌍', name: 'Europe' },\n\t\t\t'AF': { emoji: '🌍', name: 'Africa' },\n\t\t\t'SA': { emoji: '🌎', name: 'South America' },\n\t\t\t'OC': { emoji: '🌏', name: 'Oceania' },\n\t\t\t'AN': { emoji: '❄️', name: 'Antarctica' }\n\t\t};\n\n\t\tfunction englishProxyLabel(value, fallback = 'Unknown') {\n\t\t\tconst text = String(value || '').trim();\n\t\t\treturn text && !/[\\u3400-\\u9FFF]/.test(text) ? text : fallback;\n\t\t}\n\n\t\tfunction populateProxyRegionSelect(type) {\n\t\t\tconst config = proxyConfigs[type];\n\t\t\tconst select = document.getElementById(config.regionSelectId);\n\t\t\tlet html = '<option value=\"\">-- Select a region --</option>';\n\n\t\t\t// 构建按大洲m组的结构\n\t\t\tconst continentMap = {};\n\n\t\t\t// 遍历所有国家，归类到大洲\n\t\t\tfor (const [country, proxies] of Object.entries(window[config.countryMap])) {\n\t\t\t\tconst proxy = proxies[0]; // 取第一个代理获取大洲信息\n\t\t\t\tconst continent = proxy.continent || 'Unknown';\n\t\t\t\tconst continentData = continentInfo[continent] || { emoji: '🌍', name: continent };\n\n\t\t\t\tif (!continentMap[continent]) {\n\t\t\t\t\tcontinentMap[continent] = {\n\t\t\t\t\t\temoji: continentData.emoji,\n\t\t\t\t\t\tname: continentData.name,\n\t\t\t\t\t\tcountries: {}\n\t\t\t\t\t};\n\t\t\t\t}\n\n\t\t\t\tcontinentMap[continent].countries[country] = {\n\t\t\t\t\tcount: proxies.length,\n\t\t\t\t\tname: englishProxyLabel(proxy.country_en, proxy.country || country),\n\t\t\t\t\temoji: proxy.country_emoji || ''\n\t\t\t\t};\n\t\t\t}\n\n\t\t\t// 生成 HTML\n\t\t\tfor (const [continentCode, continentData] of Object.entries(continentMap)) {\n\t\t\t\tconst label = `${continentData.emoji} ${continentData.name} / ${continentCode}`;\n\t\t\t\thtml += `<optgroup label=\"${label}\">`;\n\n\t\t\t\tfor (const [country, countryData] of Object.entries(continentData.countries)) {\n\t\t\t\t\thtml += `<option value=\"${country}\">${countryData.emoji} ${countryData.name}(${countryData.count})</option>`;\n\t\t\t\t}\n\n\t\t\t\thtml += `</optgroup>`;\n\t\t\t}\n\n\t\t\tselect.innerHTML = html;\n\t\t}\n\n\t\tfunction onProxyRegionChange(type) {\n\t\t\tconst config = proxyConfigs[type];\n\t\t\tconst selectedCountry = document.getElementById(config.regionSelectId).value;\n\n\t\t\tif (!selectedCountry) {\n\t\t\t\tdocument.getElementById(config.confirmBtnId).disabled = true;\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\tconst proxies = window[config.countryMap][selectedCountry] || [];\n\n\t\t\t// 显示代理选择组\n\t\t\tdocument.getElementById(config.proxySelectGroupId).style.display = 'block';\n\n\t\t\t// 初始化每个代理的验证状态\n\t\t\tproxies.forEach(proxy => {\n\t\t\t\tif (!window[config.verificationStatus][proxy.proxy]) {\n\t\t\t\t\twindow[config.verificationStatus][proxy.proxy] = {\n\t\t\t\t\t\tstatus: 'pending', // pending, success, failed, timeout\n\t\t\t\t\t\tresponseTime: null\n\t\t\t\t\t};\n\t\t\t\t}\n\t\t\t});\n\n\t\t\t// 设置selectenable it forVerifying状态\n\t\t\tconst select = document.getElementById(config.proxySelectId);\n\t\t\tselect.innerHTML = '<option value=\"\">Checking availability, please wait...</option>';\n\n\t\t\t// 显示代理列表\n\t\t\tpopulateProxySelect(selectedCountry, config.proxySelectId, window[config.countryMap], window[config.verificationStatus]);\n\n\t\t\t// 释放之前的 AbortController 并创建新的\n\t\t\tif (config.abortController) {\n\t\t\t\tconfig.abortController.abort();\n\t\t\t}\n\t\t\tconfig.abortController = new AbortController();\n\n\t\t\t// 开始验证所有代理\n\t\t\tverifyProxies(proxies, config.verifySingleFunction, () => {\n\t\t\t\tupdateProxyDisplay(type);\n\t\t\t\t// 如果当前选中的是成功的，尝试更新地图\n\t\t\t\tupdateProxyMap(type);\n\t\t\t}, config.abortController.signal);\n\t\t}\n\n\t\t// ===== 节流更新系统：避免移动端下拉框被频繁刷新 =====\n\t\tconst PROXY_DISPLAY_UPDATE_INTERVAL = 6000; // 节流间隔：6s\n\t\tconst proxyDisplayUpdateState = {\n\t\t\tsocks5: { lastUpdate: 0, pending: false, timer: null, selectOpen: false, listenersAdded: false },\n\t\t\thttp: { lastUpdate: 0, pending: false, timer: null, selectOpen: false, listenersAdded: false },\n\t\t\thttps: { lastUpdate: 0, pending: false, timer: null, selectOpen: false, listenersAdded: false },\n\t\t\tproxyip: { lastUpdate: 0, pending: false, timer: null, selectOpen: false, listenersAdded: false }\n\t\t};\n\n\t\t// enable it for代理选择下拉框添加 focus/blur 监听，检测用户是否正InAction下拉框\n\t\tfunction ensureProxySelectListeners(type) {\n\t\t\tconst state = proxyDisplayUpdateState[type];\n\t\t\tif (state.listenersAdded) return;\n\t\t\tconst config = proxyConfigs[type];\n\t\t\tconst select = document.getElementById(config.proxySelectId);\n\t\t\tif (!select) return;\n\t\t\tselect.addEventListener('focus', () => {\n\t\t\t\tstate.selectOpen = true;\n\t\t\t});\n\t\t\tselect.addEventListener('blur', () => {\n\t\t\t\tstate.selectOpen = false;\n\t\t\t\t// 下拉框Off时，如果有待处理的更新立即执行\n\t\t\t\tif (state.pending) {\n\t\t\t\t\t_doUpdateProxyDisplay(type);\n\t\t\t\t}\n\t\t\t});\n\t\t\tstate.listenersAdded = true;\n\t\t}\n\n\t\t// 检查当前Region所有代理是否All验证完成\n\t\tfunction isAllProxiesVerified(type) {\n\t\t\tconst config = proxyConfigs[type];\n\t\t\tconst selectedCountry = document.getElementById(config.regionSelectId).value;\n\t\t\tif (!selectedCountry) return false;\n\t\t\tconst proxies = window[config.countryMap][selectedCountry] || [];\n\t\t\treturn proxies.length > 0 && proxies.every(p => {\n\t\t\t\tconst s = window[config.verificationStatus][p.proxy];\n\t\t\t\treturn s && s.status !== 'pending';\n\t\t\t});\n\t\t}\n\n\t\t// 节流版 updateProxyDisplay —— 外部统一调用此函数\n\t\t// 策略：下拉框Off时实时更新；下拉框打开时每 6 s节流更新一次\n\t\tfunction updateProxyDisplay(type) {\n\t\t\tconst state = proxyDisplayUpdateState[type];\n\t\t\tconst now = Date.now();\n\n\t\t\t// 下拉框未打开：直接实时更新\n\t\t\tif (!state.selectOpen) {\n\t\t\t\tif (state.timer) { clearTimeout(state.timer); state.timer = null; }\n\t\t\t\t_doUpdateProxyDisplay(type);\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\t// === 以下enable it for下拉框打开状态的节流逻辑 ===\n\n\t\t\t// All验证完成时强制安排一次更新（最终结果）\n\t\t\tif (isAllProxiesVerified(type)) {\n\t\t\t\tif (state.timer) { clearTimeout(state.timer); state.timer = null; }\n\t\t\t\t// 距上次更新已超过节流间隔，直接更新\n\t\t\t\tif (now - state.lastUpdate >= PROXY_DISPLAY_UPDATE_INTERVAL) {\n\t\t\t\t\t_doUpdateProxyDisplay(type);\n\t\t\t\t} else {\n\t\t\t\t\t// 未到间隔，安排一个定时器确保最终结果会被刷新\n\t\t\t\t\tstate.pending = true;\n\t\t\t\t\tif (!state.timer) {\n\t\t\t\t\t\tconst delay = PROXY_DISPLAY_UPDATE_INTERVAL - (now - state.lastUpdate);\n\t\t\t\t\t\tstate.timer = setTimeout(() => {\n\t\t\t\t\t\t\tstate.timer = null;\n\t\t\t\t\t\t\tif (state.pending) {\n\t\t\t\t\t\t\t\t_doUpdateProxyDisplay(type);\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}, delay);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\t// 节流：距上次更新不到 6 s，延迟执行\n\t\t\tif (now - state.lastUpdate < PROXY_DISPLAY_UPDATE_INTERVAL) {\n\t\t\t\tstate.pending = true;\n\t\t\t\tif (!state.timer) {\n\t\t\t\t\tconst delay = PROXY_DISPLAY_UPDATE_INTERVAL - (now - state.lastUpdate);\n\t\t\t\t\tstate.timer = setTimeout(() => {\n\t\t\t\t\t\tstate.timer = null;\n\t\t\t\t\t\tif (state.pending) {\n\t\t\t\t\t\t\t_doUpdateProxyDisplay(type);\n\t\t\t\t\t\t}\n\t\t\t\t\t}, delay);\n\t\t\t\t}\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\t// 已超过节流间隔，直接更新\n\t\t\t_doUpdateProxyDisplay(type);\n\t\t}\n\n\t\t// 实际执行更新的内部函数\n\t\tfunction _doUpdateProxyDisplay(type) {\n\t\t\tconst state = proxyDisplayUpdateState[type];\n\t\t\tstate.lastUpdate = Date.now();\n\t\t\tstate.pending = false;\n\n\t\t\tconst config = proxyConfigs[type];\n\t\t\tconst selectedCountry = document.getElementById(config.regionSelectId).value;\n\t\t\tif (selectedCountry) {\n\t\t\t\tpopulateProxySelect(selectedCountry, config.proxySelectId, window[config.countryMap], window[config.verificationStatus], type);\n\n\t\t\t\t// 更新Confirm按钮状态\n\t\t\t\tconst select = document.getElementById(config.proxySelectId);\n\t\t\t\tconst selectedValue = select.value;\n\t\t\t\tconst isValidSelected = selectedValue &&\n\t\t\t\t\twindow[config.verificationStatus][selectedValue] &&\n\t\t\t\t\twindow[config.verificationStatus][selectedValue].status === 'success';\n\t\t\t\tdocument.getElementById(config.confirmBtnId).disabled = !isValidSelected;\n\t\t\t}\n\t\t}\n\n\t\t// Reset节流状态（模态框Off时调用）\n\t\tfunction resetProxyDisplayUpdateState(type) {\n\t\t\tconst state = proxyDisplayUpdateState[type];\n\t\t\tif (state.timer) { clearTimeout(state.timer); state.timer = null; }\n\t\t\tstate.lastUpdate = 0;\n\t\t\tstate.pending = false;\n\t\t\tstate.selectOpen = false;\n\t\t}\n\n\t\tfunction confirmSelectProxy(type) {\n\t\t\tconst config = proxyConfigs[type];\n\t\t\tconst select = document.getElementById(config.proxySelectId);\n\t\t\tconst selectedProxy = select.value;\n\n\t\t\tif (!selectedProxy) {\n\t\t\t\tshowToast(`请选择一个有效的${type.toUpperCase()}代理`, 'error');\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\t// 填入Proxy Address\n\t\t\tconst input = document.getElementById(config.inputId);\n\t\t\tif (input) {\n\t\t\t\tinput.value = selectedProxy.replace(/^socks5:\\/\\/|^http:\\/\\/|^https:\\/\\/|^turn:\\/\\/|^sstp:\\/\\//, '');\n\t\t\t\tsetProxyModeSelection(type);\n\t\t\t\tupdateProxyMode(false, false);\n\t\t\t\tinput.dispatchEvent(new Event('change', { bubbles: true }));\n\t\t\t\tmarkModified('proxy');\n\t\t\t}\n\n\t\t\t// Off模态框\n\t\t\tconst modal = document.getElementById(config.modalId);\n\t\t\tif (modal) {\n\t\t\t\tmodal.classList.remove('show');\n\t\t\t}\n\n\t\t\t// 确认选择后停止剩余测试\n\t\t\tif (config.abortController) {\n\t\t\t\tconfig.abortController.abort();\n\t\t\t\tconfig.abortController = null;\n\t\t\t}\n\n\t\t\t// 亮起Save和Cancel按钮\n\t\t\tconst saveBtn = document.getElementById('saveProxyBtn');\n\t\t\tconst cancelBtn = document.getElementById('cancelProxyBtn');\n\t\t\tif (saveBtn) saveBtn.disabled = false;\n\t\t\tif (cancelBtn) cancelBtn.disabled = false;\n\t\t}\n\n\t\tfunction updateProxyConfirmButton(type) {\n\t\t\tconst config = proxyConfigs[type];\n\t\t\tconst select = document.getElementById(config.proxySelectId);\n\t\t\tconst selectedValue = select.value;\n\t\t\tconst confirmBtn = document.getElementById(config.confirmBtnId);\n\n\t\t\t// 检查选中的代理是否可用\n\t\t\tconst isValidSelected = selectedValue &&\n\t\t\t\twindow[config.verificationStatus][selectedValue] &&\n\t\t\t\twindow[config.verificationStatus][selectedValue].status === 'success';\n\n\t\t\tif (confirmBtn) {\n\t\t\t\tconfirmBtn.disabled = !isValidSelected;\n\t\t\t}\n\t\t}\n\n\t\t// 通用单个代理验证函数\n\t\tfunction verifySingleProxy(proxy, type, signal) {\n\t\t\treturn new Promise((resolve) => {\n\t\t\t\tconst config = proxyConfigs[type];\n\t\t\t\tconst protocol = proxy.protocol || type;\n\t\t\t\tconst proxyUrl = proxy.proxy;\n\t\t\t\tif (!proxyUrl) {\n\t\t\t\t\tresolve();\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tlet cleanProxy = String(proxyUrl);\n\t\t\t\tfor (const prefix of ['socks5://', 'http://', 'https://', 'turn://', 'sstp://', 'socks5=', 'http=', 'https=', 'turn=', 'sstp=']) {\n\t\t\t\t\tif (cleanProxy.toLowerCase().startsWith(prefix)) {\n\t\t\t\t\t\tcleanProxy = cleanProxy.substring(prefix.length).trim();\n\t\t\t\t\t\tbreak;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tconst checkProtocol = ['https', 'turn', 'sstp'].includes(type) ? type : protocol;\n\t\t\t\tconst checkUrl = `/admin/check?${checkProtocol}=${encodeURIComponent(cleanProxy)}&_t=${Date.now()}`;\n\n\t\t\t\t// 如果已经终止，直接返回\n\t\t\t\tif (signal && signal.aborted) {\n\t\t\t\t\treturn resolve();\n\t\t\t\t}\n\n\t\t\t\t// 设置15s超时\n\t\t\t\tconst timeoutId = setTimeout(() => {\n\t\t\t\t\twindow[config.verificationStatus][proxyUrl] = {\n\t\t\t\t\t\tstatus: 'timeout',\n\t\t\t\t\t\tresponseTime: null\n\t\t\t\t\t};\n\t\t\t\t\tupdateProxyDisplay(type);\n\t\t\t\t\tresolve();\n\t\t\t\t}, 15000);\n\n\t\t\t\twindow[config.verificationTimeouts][proxyUrl] = timeoutId;\n\n\t\t\t\tfetch(checkUrl, { signal })\n\t\t\t\t\t.then(response => response.json())\n\t\t\t\t\t.then(data => {\n\t\t\t\t\t\tclearTimeout(timeoutId);\n\t\t\t\t\t\tdelete window[config.verificationTimeouts][proxyUrl];\n\n\t\t\t\t\t\tif (data.success) {\n\t\t\t\t\t\t\twindow[config.verificationStatus][proxyUrl] = {\n\t\t\t\t\t\t\t\tstatus: 'success',\n\t\t\t\t\t\t\t\tresponseTime: data.responseTime\n\t\t\t\t\t\t\t};\n\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\twindow[config.verificationStatus][proxyUrl] = {\n\t\t\t\t\t\t\t\tstatus: 'failed',\n\t\t\t\t\t\t\t\tresponseTime: null\n\t\t\t\t\t\t\t};\n\t\t\t\t\t\t}\n\t\t\t\t\t\tupdateProxyDisplay(type);\n\t\t\t\t\t\tresolve();\n\t\t\t\t\t})\n\t\t\t\t\t.catch(error => {\n\t\t\t\t\t\tclearTimeout(timeoutId);\n\t\t\t\t\t\tdelete window[config.verificationTimeouts][proxyUrl];\n\n\t\t\t\t\t\twindow[config.verificationStatus][proxyUrl] = {\n\t\t\t\t\t\t\tstatus: 'failed',\n\t\t\t\t\t\t\tresponseTime: null\n\t\t\t\t\t\t};\n\t\t\t\t\t\tupdateProxyDisplay(type);\n\t\t\t\t\t\tresolve();\n\t\t\t\t\t});\n\t\t\t});\n\t\t}\n\n\t\t// ==================== HTTP 相关函数 ====================\n\n\t\t// 存储HTTP数据\n\t\tlet httpListData = [];\n\t\tlet httpCountryMap = {};\n\t\tlet httpVerificationStatus = {}; // 存储验证状态\n\t\tlet httpVerificationTimeouts = {}; // 存储超时计时器\n\n\t\t// 存储HTTPS数据\n\t\tlet httpsListData = [];\n\t\tlet httpsCountryMap = {};\n\t\tlet httpsVerificationStatus = {}; // 存储验证状态\n\t\tlet httpsVerificationTimeouts = {}; // 存储超时计时器\n\n\t\tfunction showExploreHTTPModal() {\n\t\t\tshowExploreProxyModal('http');\n\t\t}\n\n\t\tfunction closeExploreHTTPModal(event) {\n\t\t\tcloseExploreProxyModal('http', event);\n\t\t}\n\n\t\tfunction loadHTTPList() {\n\t\t\tloadProxyList('http');\n\t\t}\n\n\n\t\tfunction populateHTTPRegionSelect() {\n\t\t\tpopulateProxyRegionSelect('http');\n\t\t}\n\n\t\tfunction onHTTPRegionChange() {\n\t\t\tonProxyRegionChange('http');\n\t\t}\n\n\t\tfunction populateHTTPProxySelect(selectedCountry) {\n\t\t\tpopulateProxySelect(selectedCountry, 'httpProxySelect', httpCountryMap, httpVerificationStatus, 'http');\n\t\t}\n\n\t\tfunction verifyHTTPProxies(proxies) {\n\t\t\tverifyProxies(proxies, verifySingleHTTP);\n\t\t}\n\n\t\tfunction verifySingleHTTP(proxy, signal) {\n\t\t\treturn verifySingleProxy(proxy, 'http', signal);\n\t\t}\n\n\t\tfunction updateHTTPDisplay() {\n\t\t\tupdateProxyDisplay('http');\n\t\t}\n\n\t\tfunction confirmSelectHTTP() {\n\t\t\tconfirmSelectProxy('http');\n\t\t}\n\n\t\tfunction updateHTTPConfirmButton() {\n\t\t\tupdateProxyConfirmButton('http');\n\t\t}\n\n\t\tfunction showExploreHTTPSModal() {\n\t\t\tshowExploreProxyModal('https');\n\t\t}\n\n\t\tfunction closeExploreHTTPSModal(event) {\n\t\t\tcloseExploreProxyModal('https', event);\n\t\t}\n\n\t\tfunction loadHTTPSList() {\n\t\t\tloadProxyList('https');\n\t\t}\n\n\t\tfunction populateHTTPSRegionSelect() {\n\t\t\tpopulateProxyRegionSelect('https');\n\t\t}\n\n\t\tfunction onHTTPSRegionChange() {\n\t\t\tonProxyRegionChange('https');\n\t\t}\n\n\t\tfunction populateHTTPSProxySelect(selectedCountry) {\n\t\t\tpopulateProxySelect(selectedCountry, 'httpsProxySelect', httpsCountryMap, httpsVerificationStatus, 'https');\n\t\t}\n\n\t\tfunction verifyHTTPSProxies(proxies) {\n\t\t\tverifyProxies(proxies, verifySingleHTTPS);\n\t\t}\n\n\t\tfunction verifySingleHTTPS(proxy, signal) {\n\t\t\treturn verifySingleProxy(proxy, 'https', signal);\n\t\t}\n\n\t\tfunction updateHTTPSDisplay() {\n\t\t\tupdateProxyDisplay('https');\n\t\t}\n\n\t\tfunction confirmSelectHTTPS() {\n\t\t\tconfirmSelectProxy('https');\n\t\t}\n\n\t\tfunction updateHTTPSConfirmButton() {\n\t\t\tupdateProxyConfirmButton('https');\n\t\t}\n\n\t\t// ============ HOSTS 检查相关函数 ============\n\n\t\t// 检查当前访问域名是否In HOSTS 数组中\n\t\tfunction checkHostsMismatch() {\n\t\t\tconst currentHostname = window.location.hostname;\n\t\t\tconst hosts = currentConfig.HOSTS || [];\n\n\t\t\t// 检查当前 hostname 是否存In于 HOSTS 数组中\n\t\t\tconst isHostInArray = hosts.some(host => {\n\t\t\t\t// 移除端口号后进行比较\n\t\t\t\tconst hostWithoutPort = host.split(':')[0];\n\t\t\t\treturn hostWithoutPort === currentHostname;\n\t\t\t});\n\n\t\t\tif (!isHostInArray && hosts.length > 0) {\n\t\t\t\t// 检查缓存，是否In 24 h内已提示过\n\t\t\t\tif (shouldShowHostsMismatchNotification()) {\n\t\t\t\t\tshowHostsMismatchNotification(currentHostname, hosts);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\t// 检查是否应该显示 HOSTS 不匹配提示\n\t\tfunction shouldShowHostsMismatchNotification() {\n\t\t\tconst cacheKey = 'hostsMismatchNotificationTime';\n\t\t\tconst cachedTime = localStorage.getItem(cacheKey);\n\n\t\t\tif (!cachedTime) {\n\t\t\t\t// 没有缓存，应该显示\n\t\t\t\treturn true;\n\t\t\t}\n\n\t\t\tconst lastNotificationTime = parseInt(cachedTime, 10);\n\t\t\tconst currentTime = Date.now();\n\t\t\tconst twentyFourHours = 24 * 60 * 60 * 1000; // 24 h毫s数\n\n\t\t\t// 检查是否超过 24 h\n\t\t\treturn (currentTime - lastNotificationTime) > twentyFourHours;\n\t\t}\n\n\t\t// 显示 HOSTS 不匹配提示\n\t\tfunction showHostsMismatchNotification(currentHostname, hosts) {\n\t\t\t// 填充模态框中的内容\n\t\t\tconst currentHostnameEl = document.getElementById('currentHostname');\n\t\t\tconst hostToAddEl = document.getElementById('hostToAdd');\n\t\t\tconst currentHostsEl = document.getElementById('currentHosts');\n\n\t\t\tif (currentHostnameEl) {\n\t\t\t\tcurrentHostnameEl.textContent = currentHostname;\n\t\t\t}\n\t\t\tif (hostToAddEl) {\n\t\t\t\thostToAddEl.textContent = currentHostname;\n\t\t\t}\n\n\t\t\t// 填充当前 HOSTS 列表 - 用 HTML badge 而不是纯文本\n\t\t\tif (currentHostsEl) {\n\t\t\t\t// 清空并用 HTML 结构重新填充\n\t\t\t\tcurrentHostsEl.innerHTML = '';\n\n\t\t\t\thosts.forEach((host) => {\n\t\t\t\t\tconst badge = document.createElement('span');\n\t\t\t\t\tbadge.className = 'hosts-badge';\n\t\t\t\t\tbadge.textContent = host;\n\t\t\t\t\tcurrentHostsEl.appendChild(badge);\n\t\t\t\t});\n\t\t\t}\n\n\t\t\t// 显示模态框\n\t\t\tconst overlay = document.getElementById('hostsMismatchModal');\n\t\t\tif (overlay) {\n\t\t\t\tconst modal = overlay.querySelector('.modal');\n\t\t\t\toverlay.classList.add('show');\n\t\t\t\tconsole.log('✓ 域名不匹配提示已显示');\n\t\t\t} else {\n\t\t\t\tconsole.error('✗ None法找到 hostsMismatchModal 元素');\n\t\t\t}\n\t\t}\n\n\t\t// Off HOSTS 不匹配提示模态框\n\t\tfunction closeHostsMismatchModal(event) {\n\t\t\t// 如果有事件对象且点击的不是 overlay 本身，则返回\n\t\t\tif (event && event.target && event.target.id !== 'hostsMismatchModal') {\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\tconst overlay = document.getElementById('hostsMismatchModal');\n\t\t\tif (overlay) {\n\t\t\t\toverlay.classList.remove('show');\n\t\t\t}\n\t\t}\n\n\t\t// 处理\"知道了！24h内不提示\"按钮\n\t\tfunction dismissHostsMismatchNotification() {\n\t\t\tconst cacheKey = 'hostsMismatchNotificationTime';\n\t\t\tconst currentTime = Date.now();\n\n\t\t\t// 将当前时间戳Save到 localStorage\n\t\t\tlocalStorage.setItem(cacheKey, currentTime.toString());\n\n\t\t\t// Off模态框\n\t\t\tcloseHostsMismatchModal({ target: { id: 'hostsMismatchModal' } });\n\n\t\t\t// 显示确认提示\n\t\t\tshowToast('🎉 24h内不会再提示', 'info');\n\t\t}\n\n\t</script>\n\n<footer class=\"AMIR-brand-footer\">AMIR Edge Panel <span aria-hidden=\"true\">•</span> Free For All <span aria-hidden=\"true\">•</span> Developed by <a href=\"https://github.com/AMIRiran-gaming/AMIR-Edge-Panel\" target=\"_blank\" rel=\"noopener noreferrer\">AMIRIRAN</a> <span aria-hidden=\"true\">•</span> <a href=\"https://t.me/AMIR_gamingORG\" target=\"_blank\" rel=\"noopener noreferrer\">Telegram</a> <span aria-hidden=\"true\">•</span> <a href=\"https://www.youtube.com/@AMIR_Gaming\" target=\"_blank\" rel=\"noopener noreferrer\">YouTube</a></footer>\n<script id=\"AMIR-gamer-theme-js\">\n/* AMIR GAMER THEME — purely cosmetic enhancement layer (no panel logic touched) */\n(function () {\n  'use strict';\n  try {\n    var doc = document, root = doc.documentElement;\n    function ready(fn) { doc.readyState === 'loading' ? doc.addEventListener('DOMContentLoaded', fn) : fn(); }\n\n    ready(function () {\n      var reduce = false;\n      try { reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) {}\n\n      /* 1. background FX layers */\n      if (!doc.getElementById('ogFx')) {\n        var fx = doc.createElement('div');\n        fx.id = 'ogFx'; fx.setAttribute('aria-hidden', 'true');\n        fx.innerHTML = '<div class=\"og-bg\"></div><div class=\"og-floor\"></div><div class=\"og-scan\"></div><div class=\"og-vig\"></div>';\n        doc.body.insertBefore(fx, doc.body.firstChild);\n      }\n\n      /* 2. hero header: core + eyebrow + boot line */\n      var header = doc.querySelector('.card-container > .header');\n      var title = doc.getElementById('pageTitle');\n      if (header && !header.querySelector('.og-core')) {\n        var core = doc.createElement('div');\n        core.className = 'og-core'; core.setAttribute('aria-hidden', 'true');\n        core.innerHTML =\n          '<svg viewBox=\"0 0 120 120\"><defs>' +\n          '<linearGradient id=\"ogG\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"#8b5cf6\"/><stop offset=\".55\" stop-color=\"#ff4fd8\"/><stop offset=\"1\" stop-color=\"#45e9f7\"/></linearGradient>' +\n          '<radialGradient id=\"ogC\" cx=\"50%\" cy=\"50%\" r=\"50%\"><stop offset=\"0\" stop-color=\"#8b5cf6\" stop-opacity=\".55\"/><stop offset=\"1\" stop-color=\"#8b5cf6\" stop-opacity=\"0\"/></radialGradient></defs>' +\n          '<circle cx=\"60\" cy=\"60\" r=\"56\" fill=\"url(#ogC)\"/>' +\n          '<g class=\"r1\"><circle cx=\"60\" cy=\"60\" r=\"54\" fill=\"none\" stroke=\"#8b5cf6\" stroke-width=\"1.6\" stroke-dasharray=\"6 9\"/></g>' +\n          '<g class=\"r2\"><circle cx=\"60\" cy=\"60\" r=\"44\" fill=\"none\" stroke=\"#45e9f7\" stroke-width=\"1.4\" stroke-dasharray=\"30 12 4 12\"/></g>' +\n          '<g class=\"r3\"><circle cx=\"60\" cy=\"60\" r=\"34\" fill=\"none\" stroke=\"#ff4fd8\" stroke-width=\"1.2\" stroke-dasharray=\"2 8\"/></g>' +\n          '<path class=\"bolt\" d=\"M66 22 40 66h18l-6 32 30-48H64z\" fill=\"url(#ogG)\" stroke=\"#fff\" stroke-opacity=\".5\" stroke-width=\"1\"/></svg>';\n        header.insertBefore(core, header.firstChild);\n\n        var ht = header.querySelector('.header-title');\n        if (ht) {\n          var eb = doc.createElement('div');\n          eb.className = 'og-eyebrow';\n          eb.innerHTML = '<span class=\"og-live\"><i></i>LIVE</span><span class=\"og-tag\">Control Center</span>';\n          ht.insertBefore(eb, ht.firstChild);\n          var boot = doc.createElement('div');\n          boot.className = 'og-boot';\n          ht.appendChild(boot);\n          typeBoot(boot);\n        }\n\n        /* mouse tilt on core */\n        if (!reduce && window.matchMedia && window.matchMedia('(pointer:fine)').matches) {\n          var raf = 0;\n          doc.addEventListener('mousemove', function (e) {\n            if (raf) return;\n            raf = requestAnimationFrame(function () {\n              raf = 0;\n              var x = (e.clientX / innerWidth - .5), y = (e.clientY / innerHeight - .5);\n              core.style.transform = 'perspective(500px) rotateY(' + (x * 28).toFixed(1) + 'deg) rotateX(' + (-y * 28).toFixed(1) + 'deg)';\n            });\n          }, { passive: true });\n        }\n      }\n\n      /* footer: lives inside the card so it scrolls with the content */\n      var card = doc.querySelector('.card-container'), foot = doc.querySelector('footer.AMIR-brand-footer');\n      if (card && foot && foot.parentNode !== card) card.appendChild(foot);\n\n      /* 3. glitch text mirrors the (asynchronously loaded) title */\n      if (title) {\n        var sync = function () { title.setAttribute('data-og', title.textContent.trim()); };\n        sync();\n        try { new MutationObserver(sync).observe(title, { childList: true, characterData: true, subtree: true }); } catch (e) {}\n      }\n\n      /* 4. ticker strip under the header */\n      if (header && !doc.querySelector('.og-ticker')) {\n        var items = [\n          '<b>AMIR Edge Panel</b>', 'Free for all', '<em>◆</em>', 'Edge-grade routing', '<em>◆</em>', 'ECH ready',\n          '<em>◆</em>', 'FinalMask', '<em>◆</em>', 'Smart subscriptions', '<em>◆</em>', 'Zero downtime', '<em>◆</em>'\n        ];\n        var html = items.map(function (t) { return '<span>' + t + '</span>'; }).join('');\n        var tk = doc.createElement('div');\n        tk.className = 'og-ticker'; tk.setAttribute('aria-hidden', 'true');\n        tk.innerHTML = '<div class=\"og-track\">' + html + html + '</div>';\n        header.parentNode.insertBefore(tk, header.nextSibling);\n      }\n\n      /* 5. floating chips: ping + clock */\n      if (!doc.querySelector('.og-chips')) {\n        var chips = doc.createElement('div');\n        chips.className = 'og-chips'; chips.setAttribute('aria-hidden', 'true');\n        chips.innerHTML = '<div class=\"og-chip\"><i></i>PING <b id=\"ogPing\">--</b> MS</div><div class=\"og-chip\">LOCAL <b id=\"ogClock\">--:--</b></div>';\n        doc.body.appendChild(chips);\n        var pingEl = doc.getElementById('ogPing'), clockEl = doc.getElementById('ogClock');\n        var tick = function () {\n          var d = new Date();\n          clockEl.textContent = ('0' + d.getHours()).slice(-2) + ':' + ('0' + d.getMinutes()).slice(-2);\n        };\n        tick(); setInterval(tick, 15000);\n        var ping = function () {\n          if (doc.hidden) return;\n          var t0 = performance.now();\n          fetch('/cdn-cgi/trace', { cache: 'no-store' }).then(function (r) {\n            if (!r.ok) throw 0;\n            pingEl.textContent = Math.round(performance.now() - t0);\n          }).catch(function () { pingEl.textContent = '--'; });\n        };\n        ping(); setInterval(ping, 20000);\n      }\n    });\n\n    function typeBoot(el) {\n      var lines = ['> booting edge core ...', '> secure tunnel: armed', '> all systems nominal ✔'];\n      if (!window.matchMedia || window.matchMedia('(prefers-reduced-motion: reduce)').matches) { el.textContent = lines[2]; return; }\n      var li = 0, ci = 0;\n      (function step() {\n        var s = lines[li];\n        if (ci <= s.length) { el.textContent = s.slice(0, ci++); setTimeout(step, 28 + Math.random() * 30); }\n        else if (li < lines.length - 1) { li++; ci = 0; setTimeout(step, 650); }\n      })();\n    }\n  } catch (err) { /* cosmetic layer must never break the panel */ }\n})();\n</script>\n</body>\n</html>\n";

